    Op(path='backend/app/services/cases/__init__.py', kind='new', final_sha='87c90f33514de6f448401b5e57d29e020b900d76dcfdf3323e5a20b9112df4a6',
       variants=(),
       content='"""ARCH43-S1:cases — Case Intelligence (ARCH-43 Tranche 3).\n\n  dsl.py         the consistency rules (EQUAL, FUZZY_EQUAL, DATE_ORDER,\n                 WITHIN_DAYS, SUM_EQUALS). Pure.\n  doc_types.py   one document type per work item, from what the platform\n                 already knows (ARCH-31 roles, the enrichment\'s\n                 classification, the ARCH-43 page classifier).\n  templates.py   draft -> publish (immutable) -> retire; versions.\n  assembly.py    documents into cases by ARCH-42 entity root, ARCH-38 batch or\n                 by hand; completeness + rules -> status; triggers\n                 case.completed / case.inconsistent.\n  requests.py    missing-document requests: single-use, expiring tokens\n                 stored only as SHA-256.\n"""\n'),
    Op(path='backend/app/services/cases/assembly.py', kind='new', final_sha='2f1d654361c6204ce580e763b3f796a3cf7c22773170891f698d6518510a84e2',
       variants=(),
       content='"""ARCH43-S1:assembly — documents into cases, and a case\'s verdict.\n\nassemble_work_item(): for every PUBLISHED template in the workspace that\nnames the document\'s type, find the case\'s ANCHOR -- the ARCH-42 canonical\nroot of the entity of the template\'s kind (and role) this document mentions,\nor the ARCH-38 batch it arrived in -- and add the document to the one live\ncase for (template, anchor), creating it if needed. A split packet\'s parent\nis never assembled: its children are (roadmap adjustment 4).\n\nevaluate(): completeness over the required slots, every rule through the\nDSL, status INCONSISTENT (any FAIL) > COMPLETE (all slots, all PASS) >\nINCOMPLETE. Entering COMPLETE emits trigger.case.completed; entering\nINCONSISTENT emits trigger.case.inconsistent (once per transition, keyed on\nthe case revision).\n"""\n\nfrom __future__ import annotations\n\nimport uuid\nfrom collections import defaultdict\nfrom datetime import datetime, timezone\nfrom decimal import Decimal\nfrom typing import Any, Optional\n\nfrom sqlalchemy import select, text\nfrom sqlalchemy.dialects.postgresql import insert as pg_insert\nfrom sqlalchemy.orm import Session\n\nfrom app.models.cases import Case, CaseDocument, CaseRuleResult, CaseTemplate\nfrom app.models.work_item import WorkItem\nfrom app.services.cases import doc_types, dsl, templates\nfrom app.services.cases import vocabulary as v\n\n\ndef now() -> datetime:\n    return datetime.now(timezone.utc)\n\n\ndef _entity_anchors(db: Session, work_item: WorkItem, template: CaseTemplate) -> list[tuple[uuid.UUID, str]]:\n    from app.services.entities import graph\n\n    sql = ("SELECT entity_id FROM entity_mentions WHERE work_item_id = :w AND workspace_id = :ws "\n           "AND superseded_at IS NULL AND entity_kind = :k AND decision IN (\'AUTO\', \'CONFIRMED\')")\n    params: dict[str, Any] = {"w": work_item.id, "ws": work_item.workspace_id, "k": template.entity_kind}\n    if template.entity_role:\n        sql += " AND role = :r"\n        params["r"] = template.entity_role\n    roots: dict[uuid.UUID, str] = {}\n    for (entity_id,) in db.execute(text(sql), params).all():\n        root = graph.root_of(db, entity_id)\n        roots[root.id] = root.display_name\n    return list(roots.items())\n\n\ndef _batch_anchor(db: Session, work_item: WorkItem) -> Optional[tuple[uuid.UUID, str]]:\n    row = db.execute(text("SELECT b.id, \'Batch \' || left(b.id::text, 8) FROM ingestion_batch_items i "\n                          "JOIN ingestion_batches b ON b.id = i.batch_id WHERE i.work_item_id = :w LIMIT 1"),\n                     {"w": work_item.id}).first()\n    return (row[0], row[1]) if row else None\n\n\ndef live_case(db: Session, template: CaseTemplate, *, entity_id=None, batch_id=None) -> Optional[Case]:\n    query = select(Case).where(Case.template_id == template.id, Case.status != v.CASE_CLOSED)\n    query = query.where(Case.anchor_entity_id == entity_id) if entity_id else query.where(Case.anchor_batch_id == batch_id)\n    return db.execute(query).scalar_one_or_none()\n\n\ndef open_case(db: Session, template: CaseTemplate, *, anchor_kind: str, title: str, entity_id=None, batch_id=None,\n              actor_user_id: Optional[uuid.UUID] = None) -> Case:\n    if anchor_kind != v.ASSEMBLY_MANUAL:\n        existing = live_case(db, template, entity_id=entity_id, batch_id=batch_id)\n        if existing is not None:\n            return existing\n    case = Case(id=uuid.uuid4(), organization_id=template.organization_id, workspace_id=template.workspace_id,\n                template_id=template.id, anchor_kind=anchor_kind, anchor_entity_id=entity_id, anchor_batch_id=batch_id,\n                title=f"{template.name} — {title}"[:300], status=v.CASE_INCOMPLETE, completeness=Decimal("0"),\n                created_by_user_id=actor_user_id)\n    db.add(case)\n    db.flush()\n    return case\n\n\ndef add_document(db: Session, *, case: Case, work_item_id: uuid.UUID, document_type: str, source: str,\n                 actor_user_id: Optional[uuid.UUID] = None) -> bool:\n    result = db.execute(pg_insert(CaseDocument).values(\n        id=uuid.uuid4(), case_id=case.id, workspace_id=case.workspace_id, work_item_id=work_item_id,\n        document_type=document_type, source=source, added_by_user_id=actor_user_id,\n    ).on_conflict_do_nothing(constraint="uq_case_documents_case_item"))\n    db.flush()\n    return bool(result.rowcount)\n\n\ndef assemble_work_item(db: Session, *, work_item: WorkItem) -> dict[str, Any]:\n    from app.services.packets import lineage\n\n    if lineage.is_split_parent(db, work_item.id):\n        return {"assembled": 0, "reason": "a split packet is represented by its children"}\n    doc_type = doc_types.document_type_of(db, work_item)\n    if not doc_type:\n        return {"assembled": 0, "reason": "document type unknown"}\n    report: dict[str, Any] = {"document_type": doc_type, "assembled": 0, "cases": []}\n    published = db.execute(select(CaseTemplate).where(CaseTemplate.workspace_id == work_item.workspace_id,\n                                                      CaseTemplate.status == v.TEMPLATE_PUBLISHED)).scalars()\n    for template in published:\n        if doc_type not in templates.document_types(template) or template.assembly_key == v.ASSEMBLY_MANUAL:\n            continue\n        if template.assembly_key == v.ASSEMBLY_ENTITY:\n            anchors = [dict(entity_id=e, title=name) for e, name in _entity_anchors(db, work_item, template)]\n        else:\n            batch = _batch_anchor(db, work_item)\n            anchors = [dict(batch_id=batch[0], title=batch[1])] if batch else []\n        for anchor in anchors:\n            case = open_case(db, template, anchor_kind=template.assembly_key, **anchor)\n            if add_document(db, case=case, work_item_id=work_item.id, document_type=doc_type, source=v.SOURCE_AUTO):\n                report["assembled"] += 1\n            evaluate(db, case=case)\n            report["cases"].append(str(case.id))\n    return report\n\n\ndef _fields_by_type(db: Session, case: Case) -> dict[str, list[dict[str, Any]]]:\n    rows = db.execute(select(CaseDocument.document_type, WorkItem.extracted_entities, WorkItem.created_at)\n                      .join(WorkItem, WorkItem.id == CaseDocument.work_item_id)\n                      .where(CaseDocument.case_id == case.id).order_by(WorkItem.created_at)).all()\n    out: dict[str, list[dict[str, Any]]] = defaultdict(list)\n    for doc_type, fields, _ in rows:\n        out[doc_type].append(fields if isinstance(fields, dict) else {})\n    return out\n\n\ndef checklist(db: Session, case: Case, template: Optional[CaseTemplate] = None) -> list[dict[str, Any]]:\n    template = template or db.get(CaseTemplate, case.template_id)\n    counts: dict[str, int] = defaultdict(int)\n    for (doc_type,) in db.execute(select(CaseDocument.document_type).where(CaseDocument.case_id == case.id)).all():\n        counts[doc_type] += 1\n    return [{**slot, "present": counts.get(slot["doc_type"], 0), "satisfied": counts.get(slot["doc_type"], 0) >= slot["min_count"]}\n            for slot in template.required_documents or []]\n\n\ndef evaluate(db: Session, *, case: Case) -> dict[str, Any]:\n    from app.services import outbox_service\n\n    if case.status == v.CASE_CLOSED:\n        return {"status": case.status}\n    template = db.get(CaseTemplate, case.template_id)\n    slots = checklist(db, case, template)\n    satisfied = sum(1 for s in slots if s["satisfied"])\n    docs = _fields_by_type(db, case)\n    outcomes = [dsl.evaluate(rule, docs) for rule in template.rules or []]\n    db.execute(CaseRuleResult.__table__.delete().where(CaseRuleResult.case_id == case.id))\n    for o in outcomes:\n        db.add(CaseRuleResult(id=uuid.uuid4(), case_id=case.id, workspace_id=case.workspace_id, rule_id=o.rule_id, op=o.op,\n                              outcome=o.outcome, left_value=o.left, right_value=o.right, detail=o.detail))\n    failed = [o.rule_id for o in outcomes if o.outcome == dsl.FAIL]\n    complete = satisfied == len(slots) and all(o.outcome == dsl.PASS for o in outcomes)\n    status = v.CASE_INCONSISTENT if failed else v.CASE_COMPLETE if complete else v.CASE_INCOMPLETE\n    previous = case.status\n    case.status = status\n    case.completeness = Decimal(str(round(satisfied / len(slots), 4))) if slots else Decimal("1")\n    case.revision += 1\n    case.evaluated_at = now()\n    if status == v.CASE_COMPLETE and previous != v.CASE_COMPLETE:\n        case.completed_at = case.evaluated_at\n    db.flush()\n    event = (v.EVENT_CASE_COMPLETED if status == v.CASE_COMPLETE else v.EVENT_CASE_INCONSISTENT) \\\n        if status != previous and status in (v.CASE_COMPLETE, v.CASE_INCONSISTENT) else None\n    if event is not None:\n        outbox_service.emit_trigger(\n            db, organization_id=case.organization_id, workspace_id=case.workspace_id, event_type=event,\n            resource_id=case.id, idempotency_key=f"{event}:{case.id}:{case.revision}",\n            payload={"case_id": str(case.id), "template_key": template.key, "template_version": template.version,\n                     "title": case.title, "status": status, "documents": sum(len(x) for x in docs.values()),\n                     "completeness": float(case.completeness), "failed_rules": failed})\n    return {"status": status, "previous": previous, "completeness": float(case.completeness), "failed_rules": failed,\n            "event": event}\n\n\ndef close(db: Session, *, case: Case) -> Case:\n    case.status, case.closed_at = v.CASE_CLOSED, now()\n    db.flush()\n    return case\n\n\n__all__ = ["add_document", "assemble_work_item", "checklist", "close", "evaluate", "live_case", "open_case"]\n'),
    Op(path='backend/app/services/cases/doc_types.py', kind='new', final_sha='1d7166ddeebbb82bbbef9539b792e2ee33e86aff458ae7d0d493b3433d189480',
       variants=(),
       content='"""ARCH43-S1:doc-types — one document type per work item.\n\nIn order of trust: an ARCH-31 role a person set or the classifier stored\n(document_roles, not OTHER); the enrichment\'s `document_classification`\nmapped onto the preset keys; the ARCH-43 page classifier over the first\npages. Types are lowercase keys (invoice, purchase_order, resume,\nbill_of_lading, ...), the same keys case templates require.\n"""\n\nfrom __future__ import annotations\n\nimport re\nfrom typing import Any, Optional\n\nfrom sqlalchemy import text\nfrom sqlalchemy.orm import Session\n\nfrom app.services.packets import page_classifier as pc\n\nSYNONYMS = {\n    "tax_invoice": "invoice", "commercial_invoice": "invoice", "bill": "invoice", "po": "purchase_order",\n    "grn": "goods_receipt", "goods_receipt_note": "goods_receipt", "delivery_challan": "goods_receipt",\n    "delivery_note": "goods_receipt", "cv": "resume", "curriculum_vitae": "resume", "b_l": "bill_of_lading",\n    "bol": "bill_of_lading", "aadhaar": "india_id_card", "pan_card": "india_id_card", "statement_of_account": "statement",\n    "contract": "contract", "master_services_agreement": "msa", "non_disclosure_agreement": "nda",\n}\n\n\ndef normalise(label: Any) -> Optional[str]:\n    if not label:\n        return None\n    key = re.sub(r"[^a-z0-9]+", "_", str(label).strip().lower()).strip("_")\n    if not key or key in ("other", "unknown", "none"):\n        return None\n    return SYNONYMS.get(key, key)[:64]\n\n\ndef document_type_of(db: Session, work_item: Any) -> Optional[str]:\n    try:\n        role = db.execute(text("SELECT role FROM document_roles WHERE work_item_id = :w"), {"w": work_item.id}).scalar()\n    except Exception:  # noqa: BLE001 - no roles table on an old schema is "no role"\n        role = None\n    if role and role != "OTHER":\n        return normalise(role)\n    fields = work_item.extracted_entities if isinstance(work_item.extracted_entities, dict) else {}\n    classified = normalise(fields.get("document_classification") or fields.get("document_type"))\n    if classified:\n        return classified\n    first = "\\n".join((work_item.extracted_text or "").splitlines()[:80])\n    verdict = pc.classify_page(first)\n    return None if verdict.doc_type == pc.OTHER else verdict.doc_type\n'),
    Op(path='backend/app/services/cases/dsl.py', kind='new', final_sha='3f00b4476e57c961984be2f9a8c3812d436b920352d431b5899cddbd39efb5a7',
       variants=(),
       content='"""ARCH43-S1:dsl — the case consistency rules. Pure; no I/O.\n\nA rule compares values extracted from the case\'s documents:\n\n  EQUAL        left == right (normalised: case, spacing, punctuation)\n  FUZZY_EQUAL  Jaro-Winkler(left, right) >= threshold (default 0.92), on\n               names normalised with ARCH-42\'s organisation/person rules\n  DATE_ORDER   left <= right (dates parsed with ARCH-42\'s parser)\n  WITHIN_DAYS  |right - left| <= days\n  SUM_EQUALS   sum(terms) == right, within tolerance (default 0.01). A term\n               sums the field over EVERY case document of its type, so\n               "the invoices add up to the PO" is one rule.\n\nAn operand is {"doc_type": ..., "field": ...}. Outcomes: PASS, FAIL, MISSING\n(no document of that type yet, or the field is absent) and ERROR (a value\nthat will not parse as a number or date). Only PASS and FAIL are verdicts;\nMISSING keeps a case INCOMPLETE rather than failing it.\n"""\n\nfrom __future__ import annotations\n\nimport re\nfrom dataclasses import dataclass, field\nfrom datetime import date\nfrom decimal import Decimal, InvalidOperation\nfrom typing import Any, Mapping, Optional, Sequence\n\nfrom app.services.entities import normalize as n\n\nOPS = ("EQUAL", "FUZZY_EQUAL", "DATE_ORDER", "WITHIN_DAYS", "SUM_EQUALS")\nPASS, FAIL, MISSING, ERROR = "PASS", "FAIL", "MISSING", "ERROR"\nDEFAULT_FUZZY = 0.92\nDEFAULT_TOLERANCE = Decimal("0.01")\n_RULE_ID = re.compile(r"^[a-z0-9][a-z0-9_\\-]{0,63}$")\n_DOC_TYPE = re.compile(r"^[a-z][a-z0-9_]{1,63}$")\n\n\nclass RuleError(ValueError):\n    """A rule the DSL cannot run. Refused when the template is saved."""\n\n\n@dataclass(frozen=True)\nclass Outcome:\n    rule_id: str\n    op: str\n    outcome: str\n    left: Optional[str] = None\n    right: Optional[str] = None\n    detail: dict[str, Any] = field(default_factory=dict)\n\n\ndef _operand(value: Any, where: str) -> dict[str, str]:\n    if not isinstance(value, Mapping) or not isinstance(value.get("doc_type"), str) or not isinstance(value.get("field"), str):\n        raise RuleError(f"{where} must be {{doc_type, field}}")\n    if not _DOC_TYPE.match(value["doc_type"]):\n        raise RuleError(f"{where}.doc_type {value[\'doc_type\']!r} is not a document type key")\n    if not value["field"].strip():\n        raise RuleError(f"{where}.field is empty")\n    return {"doc_type": value["doc_type"], "field": value["field"].strip()}\n\n\ndef validate_rule(rule: Any) -> dict[str, Any]:\n    if not isinstance(rule, Mapping):\n        raise RuleError("a rule must be an object")\n    rid, op = str(rule.get("id") or ""), str(rule.get("op") or "").upper()\n    if not _RULE_ID.match(rid):\n        raise RuleError(f"rule id {rid!r} must be 1-64 lowercase letters, digits, - or _")\n    if op not in OPS:\n        raise RuleError(f"rule {rid}: op must be one of {\', \'.join(OPS)}")\n    out: dict[str, Any] = {"id": rid, "op": op, "label": str(rule.get("label") or rid)[:200]}\n    if op == "SUM_EQUALS":\n        terms = rule.get("terms")\n        if not isinstance(terms, Sequence) or isinstance(terms, (str, bytes)) or not terms:\n            raise RuleError(f"rule {rid}: SUM_EQUALS needs a non-empty terms list")\n        out["terms"] = [_operand(t, f"rule {rid}.terms[{i}]") for i, t in enumerate(terms)]\n        out["right"] = _operand(rule.get("right"), f"rule {rid}.right")\n        try:\n            out["tolerance"] = str(Decimal(str(rule.get("tolerance", DEFAULT_TOLERANCE))))\n        except InvalidOperation as exc:\n            raise RuleError(f"rule {rid}: tolerance is not a number") from exc\n        return out\n    out["left"] = _operand(rule.get("left"), f"rule {rid}.left")\n    out["right"] = _operand(rule.get("right"), f"rule {rid}.right")\n    if op == "FUZZY_EQUAL":\n        threshold = float(rule.get("threshold", DEFAULT_FUZZY))\n        if not 0.5 <= threshold <= 1.0:\n            raise RuleError(f"rule {rid}: threshold must be between 0.5 and 1")\n        out["threshold"] = threshold\n    if op == "WITHIN_DAYS":\n        days = rule.get("days")\n        if not isinstance(days, int) or isinstance(days, bool) or days < 0:\n            raise RuleError(f"rule {rid}: WITHIN_DAYS needs a whole number of days")\n        out["days"] = days\n    return out\n\n\ndef validate_rules(rules: Any) -> list[dict[str, Any]]:\n    if not isinstance(rules, list):\n        raise RuleError("rules must be a list")\n    checked = [validate_rule(r) for r in rules]\n    ids = [r["id"] for r in checked]\n    if len(set(ids)) != len(ids):\n        raise RuleError("rule ids must be unique within a template")\n    return checked\n\n\ndef doc_types_of(rules: Sequence[Mapping[str, Any]]) -> set[str]:\n    out: set[str] = set()\n    for r in rules:\n        for key in ("left", "right"):\n            if isinstance(r.get(key), Mapping):\n                out.add(r[key]["doc_type"])\n        for term in r.get("terms") or []:\n            out.add(term["doc_type"])\n    return out\n\n\ndef field_value(fields: Mapping[str, Any], name: str) -> Any:\n    if name in fields:\n        return fields[name]\n    wanted = re.sub(r"[\\s\\-]+", "_", name.strip().lower())\n    for key, value in fields.items():\n        if re.sub(r"[\\s\\-]+", "_", str(key).strip().lower()) == wanted:\n            return value\n    return None\n\n\ndef _number(value: Any) -> Decimal:\n    if isinstance(value, bool):\n        raise InvalidOperation\n    if isinstance(value, (int, float, Decimal)):\n        return Decimal(str(value))\n    text = re.sub(r"[^\\d.\\-]", "", str(value).replace(",", ""))\n    if text in ("", "-", ".", "-."):\n        raise InvalidOperation\n    return Decimal(text)\n\n\ndef _date(value: Any) -> date:\n    iso = n.parse_date(str(value))\n    if not iso:\n        raise ValueError(f"not a date: {value!r}")\n    return date.fromisoformat(iso)\n\n\ndef _plain(value: Any) -> str:\n    return re.sub(r"\\s+", " ", re.sub(r"[^\\w\\s]", " ", str(value).lower())).strip()\n\n\ndef _fuzzy_norm(value: Any) -> str:\n    text = str(value)\n    org = n.normalize_organization(text)\n    return org or n.normalize_person(text) or _plain(text)\n\n\nDocuments = Mapping[str, Sequence[Mapping[str, Any]]]  # doc_type -> extracted fields of each document\n\n\ndef _first(docs: Documents, operand: Mapping[str, str]) -> Any:\n    for fields in docs.get(operand["doc_type"], ()):\n        value = field_value(fields, operand["field"])\n        if value not in (None, "", []):\n            return value\n    return None\n\n\ndef evaluate(rule: Mapping[str, Any], docs: Documents) -> Outcome:\n    rid, op = rule["id"], rule["op"]\n    try:\n        if op == "SUM_EQUALS":\n            total = Decimal("0")\n            seen = 0\n            for term in rule["terms"]:\n                for fields in docs.get(term["doc_type"], ()):\n                    value = field_value(fields, term["field"])\n                    if value in (None, ""):\n                        continue\n                    total += _number(value)\n                    seen += 1\n            right = _first(docs, rule["right"])\n            if not seen or right is None:\n                return Outcome(rid, op, MISSING, str(total) if seen else None, None if right is None else str(right))\n            target = _number(right)\n            ok = abs(total - target) <= Decimal(rule.get("tolerance") or DEFAULT_TOLERANCE)\n            return Outcome(rid, op, PASS if ok else FAIL, str(total), str(target), {"terms": seen, "difference": str(total - target)})\n        left, right = _first(docs, rule["left"]), _first(docs, rule["right"])\n        if left is None or right is None:\n            return Outcome(rid, op, MISSING, None if left is None else str(left), None if right is None else str(right))\n        if op == "EQUAL":\n            return Outcome(rid, op, PASS if _plain(left) == _plain(right) else FAIL, str(left), str(right))\n        if op == "FUZZY_EQUAL":\n            score = n.jaro_winkler(_fuzzy_norm(left), _fuzzy_norm(right))\n            threshold = float(rule.get("threshold", DEFAULT_FUZZY))\n            return Outcome(rid, op, PASS if score >= threshold else FAIL, str(left), str(right),\n                           {"similarity": round(score, 4), "threshold": threshold})\n        a, b = _date(left), _date(right)\n        if op == "DATE_ORDER":\n            return Outcome(rid, op, PASS if a <= b else FAIL, a.isoformat(), b.isoformat())\n        days = abs((b - a).days)\n        return Outcome(rid, op, PASS if days <= int(rule["days"]) else FAIL, a.isoformat(), b.isoformat(),\n                       {"days": days, "limit": int(rule["days"])})\n    except (InvalidOperation, ValueError, TypeError) as exc:\n        return Outcome(rid, op, ERROR, detail={"error": str(exc)[:200]})\n\n\n__all__ = ["DEFAULT_FUZZY", "ERROR", "FAIL", "MISSING", "OPS", "Outcome", "PASS", "RuleError", "doc_types_of",\n           "evaluate", "field_value", "validate_rule", "validate_rules"]\n'),
    Op(path='backend/app/services/cases/requests.py', kind='new', final_sha='78acc86ec1bbb352e848e064d222bf69deee8614920bd051268546675b495e5c',
       variants=(),
       content='"""ARCH43-S1:requests — missing-document requests with single-use tokens.\n\nThe token is 32 random bytes shown ONCE to the person who creates the\nrequest; the database keeps only its SHA-256 (ck_document_requests_token_hash\nrefuses anything else). consume() is one conditional UPDATE -- status OPEN\nand not expired, set FULFILLED -- so two concurrent uploads cannot both use\nit, and a used, expired or revoked token is refused before any file is read.\n"""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport secrets\nimport uuid\nfrom datetime import datetime, timedelta, timezone\nfrom typing import Any, Optional\n\nfrom sqlalchemy import select, update\nfrom sqlalchemy.orm import Session\n\nfrom app.models.cases import Case, CaseTemplate, DocumentRequest\nfrom app.services.cases import vocabulary as v\n\n\nclass RequestError(ValueError):\n    def __init__(self, code: str, message: str) -> None:\n        super().__init__(message)\n        self.code = code\n\n\ndef digest(token: str) -> str:\n    return hashlib.sha256(token.encode("utf-8")).hexdigest()\n\n\ndef create(db: Session, *, case: Case, document_type: str, recipient_label: str, actor_user_id: Optional[uuid.UUID],\n           ttl_hours: Optional[int] = None) -> tuple[DocumentRequest, str]:\n    if case.status == v.CASE_CLOSED:\n        raise RequestError("CASE_CLOSED", "a closed case cannot request documents")\n    template = db.get(CaseTemplate, case.template_id)\n    token = secrets.token_urlsafe(32)\n    hours = int(ttl_hours or template.request_ttl_hours)\n    if not 1 <= hours <= 2160:\n        raise RequestError("INVALID_TTL", "ttl_hours must be 1-2160")\n    request = DocumentRequest(id=uuid.uuid4(), organization_id=case.organization_id, workspace_id=case.workspace_id,\n                              case_id=case.id, document_type=document_type[:64], recipient_label=recipient_label[:200],\n                              token_hash=digest(token), status=v.REQUEST_OPEN,\n                              created_at=datetime.now(timezone.utc),\n                              expires_at=datetime.now(timezone.utc) + timedelta(hours=hours), created_by_user_id=actor_user_id)\n    db.add(request)\n    db.flush()\n    return request, token\n\n\ndef peek(db: Session, token: str) -> DocumentRequest:\n    request = db.execute(select(DocumentRequest).where(DocumentRequest.token_hash == digest(token))).scalar_one_or_none()\n    if request is None:\n        raise RequestError("UNKNOWN", "This link is not valid.")\n    if request.status == v.REQUEST_OPEN and request.expires_at <= datetime.now(timezone.utc):\n        raise RequestError("EXPIRED", "This link has expired.")\n    if request.status != v.REQUEST_OPEN:\n        raise RequestError(request.status, "This link has already been used or withdrawn.")\n    return request\n\n\ndef consume(db: Session, token: str) -> DocumentRequest:\n    row = db.execute(\n        update(DocumentRequest)\n        .where(DocumentRequest.token_hash == digest(token), DocumentRequest.status == v.REQUEST_OPEN,\n               DocumentRequest.expires_at > datetime.now(timezone.utc))\n        .values(status=v.REQUEST_FULFILLED, used_at=datetime.now(timezone.utc))\n        .returning(DocumentRequest.id)\n        .execution_options(synchronize_session=False)\n    ).first()\n    if row is None:\n        raise RequestError("USED", "This link has already been used, has expired or was withdrawn.")\n    request = db.get(DocumentRequest, row[0])\n    db.refresh(request)\n    return request\n\n\ndef revoke(db: Session, *, request: DocumentRequest) -> DocumentRequest:\n    if request.status != v.REQUEST_OPEN:\n        raise RequestError("NOT_OPEN", "only an open request can be withdrawn")\n    request.status = v.REQUEST_REVOKED\n    db.flush()\n    return request\n\n\ndef expire(db: Session) -> int:\n    result = db.execute(update(DocumentRequest).where(DocumentRequest.status == v.REQUEST_OPEN,\n                                                      DocumentRequest.expires_at <= datetime.now(timezone.utc))\n                        .values(status=v.REQUEST_EXPIRED).execution_options(synchronize_session=False))\n    return int(result.rowcount or 0)\n\n\ndef fulfil_upload(db: Session, *, token: str, handle: Any, size: int, filename: str, declared_mime: Optional[str]) -> dict[str, Any]:\n    """Validate the file, consume the token, ingest into the case\'s workspace, add to the case, re-evaluate.\n    One transaction: if intake fails, the token is still unused."""\n    from app.core.config import settings\n    from app.models.work_item import WorkItem\n    from app.services import document_intake_service, file_validation_service\n    from app.services.cases import assembly\n\n    pending = peek(db, token)\n    validated = file_validation_service.validate_spooled(\n        handle, size, declared_mime=declared_mime, original_filename=filename[:255],\n        allowed_mimes=file_validation_service.workspace_allowed_mimes(db, pending.workspace_id, settings.ALLOWED_MIME_TYPES),\n        max_pages=settings.MAX_DOCUMENT_PAGES, scrub_metadata=settings.SCRUB_UPLOAD_METADATA)\n    request = consume(db, token)\n    with validated:\n        result = document_intake_service.ingest_validated(\n            db, validated, organization_id=request.organization_id, workspace_id=request.workspace_id,\n            uploader_id=None, enqueue_extraction=True)\n    item: WorkItem = result.work_item\n    request.fulfilled_work_item_id = item.id\n    case = db.get(Case, request.case_id)\n    assembly.add_document(db, case=case, work_item_id=item.id, document_type=request.document_type, source=v.SOURCE_REQUEST)\n    assembly.evaluate(db, case=case)\n    db.flush()\n    return {"received": True, "document_type": request.document_type, "work_item_id": str(item.id)}\n\n\n__all__ = ["RequestError", "consume", "create", "digest", "expire", "fulfil_upload", "peek", "revoke"]\n'),
    Op(path='backend/app/services/cases/templates.py', kind='new', final_sha='2fd2e5a0817d232a2c943cfbf8f54eeafdd48975e49147a8f11b46f0b1946878',
       variants=(),
       content='"""ARCH43-S1:templates — case templates: draft, publish (immutable), retire.\n\nA published template is immutable (the database trigger refuses any change\nto its content, and deleting it); changing one means publishing version n+1,\nwhich retires version n in the same transaction. Cases keep pointing at the\nversion they were assembled under, so a rule change never silently re-grades\nyesterday\'s cases.\n"""\n\nfrom __future__ import annotations\n\nimport re\nimport uuid\nfrom datetime import datetime, timezone\nfrom typing import Any, Optional\n\nfrom sqlalchemy import func, select\nfrom sqlalchemy.orm import Session\n\nfrom app.models.cases import CaseTemplate\nfrom app.services.cases import dsl\nfrom app.services.cases import vocabulary as v\n\n_KEY = re.compile(r"^[a-z0-9][a-z0-9_\\-]{1,63}$")\n_DOC = re.compile(r"^[a-z][a-z0-9_]{1,63}$")\n\n\nclass TemplateError(ValueError):\n    def __init__(self, code: str, message: str) -> None:\n        super().__init__(message)\n        self.code = code\n\n\ndef validate_required(required: Any) -> list[dict[str, Any]]:\n    if not isinstance(required, list) or not required or len(required) > v.MAX_REQUIRED:\n        raise TemplateError("INVALID_REQUIRED", f"required_documents must list 1-{v.MAX_REQUIRED} document types")\n    out, seen = [], set()\n    for item in required:\n        doc_type = str((item or {}).get("doc_type") or "") if isinstance(item, dict) else ""\n        if not _DOC.match(doc_type) or doc_type in seen:\n            raise TemplateError("INVALID_REQUIRED", f"{doc_type!r} is not a unique document type key")\n        seen.add(doc_type)\n        min_count = int(item.get("min_count", 1))\n        if not 1 <= min_count <= 50:\n            raise TemplateError("INVALID_REQUIRED", f"{doc_type}: min_count must be 1-50")\n        out.append({"doc_type": doc_type, "label": str(item.get("label") or doc_type.replace("_", " ").title())[:120],\n                    "min_count": min_count})\n    return out\n\n\ndef validate(payload: dict[str, Any]) -> dict[str, Any]:\n    key = str(payload.get("key") or "").strip().lower()\n    if not _KEY.match(key):\n        raise TemplateError("INVALID_KEY", "key must be 2-64 lowercase letters, digits, - or _")\n    assembly = str(payload.get("assembly_key") or v.ASSEMBLY_MANUAL).upper()\n    if assembly not in v.ASSEMBLY_KEYS:\n        raise TemplateError("INVALID_ASSEMBLY", f"assembly_key must be one of {\', \'.join(v.ASSEMBLY_KEYS)}")\n    entity_kind = payload.get("entity_kind")\n    if assembly == v.ASSEMBLY_ENTITY:\n        entity_kind = str(entity_kind or "").upper()\n        if entity_kind not in v.ENTITY_KINDS:\n            raise TemplateError("INVALID_ENTITY_KIND", f"entity_kind must be one of {\', \'.join(v.ENTITY_KINDS)}")\n    else:\n        entity_kind = None\n    try:\n        rules = dsl.validate_rules(payload.get("rules") or [])\n    except dsl.RuleError as exc:\n        raise TemplateError("INVALID_RULE", str(exc)) from exc\n    if len(rules) > v.MAX_RULES:\n        raise TemplateError("INVALID_RULE", f"at most {v.MAX_RULES} rules")\n    ttl = int(payload.get("request_ttl_hours") or 72)\n    if not 1 <= ttl <= 2160:\n        raise TemplateError("INVALID_TTL", "request_ttl_hours must be 1-2160")\n    name = str(payload.get("name") or "").strip()\n    if not name:\n        raise TemplateError("INVALID_NAME", "name is required")\n    return {"key": key, "name": name[:160], "description": str(payload.get("description") or "")[:4000],\n            "assembly_key": assembly, "entity_kind": entity_kind,\n            "entity_role": (str(payload["entity_role"]).strip().lower()[:48] or None) if payload.get("entity_role") else None,\n            "required_documents": validate_required(payload.get("required_documents")), "rules": rules,\n            "request_ttl_hours": ttl}\n\n\ndef create(db: Session, *, organization_id: uuid.UUID, workspace_id: uuid.UUID, payload: dict[str, Any],\n           actor_user_id: Optional[uuid.UUID]) -> CaseTemplate:\n    clean = validate(payload)\n    version = (db.execute(select(func.max(CaseTemplate.version)).where(\n        CaseTemplate.workspace_id == workspace_id, CaseTemplate.key == clean["key"])).scalar() or 0) + 1\n    draft = db.execute(select(CaseTemplate).where(CaseTemplate.workspace_id == workspace_id, CaseTemplate.key == clean["key"],\n                                                  CaseTemplate.status == v.TEMPLATE_DRAFT)).scalar_one_or_none()\n    if draft is not None:\n        raise TemplateError("DRAFT_EXISTS", f"{clean[\'key\']} already has a draft (v{draft.version}); edit that")\n    template = CaseTemplate(id=uuid.uuid4(), organization_id=organization_id, workspace_id=workspace_id, version=version,\n                            status=v.TEMPLATE_DRAFT, created_by_user_id=actor_user_id, **clean)\n    db.add(template)\n    db.flush()\n    return template\n\n\ndef update_draft(db: Session, *, template: CaseTemplate, payload: dict[str, Any]) -> CaseTemplate:\n    if template.status != v.TEMPLATE_DRAFT:\n        raise TemplateError("IMMUTABLE", "a published template cannot change; create a new version")\n    clean = validate({**payload, "key": template.key})\n    for attr, value in clean.items():\n        setattr(template, attr, value)\n    db.flush()\n    return template\n\n\ndef publish(db: Session, *, template: CaseTemplate) -> CaseTemplate:\n    if template.status != v.TEMPLATE_DRAFT:\n        raise TemplateError("NOT_DRAFT", "only a draft can be published")\n    now = datetime.now(timezone.utc)\n    for old in db.execute(select(CaseTemplate).where(CaseTemplate.workspace_id == template.workspace_id,\n                                                     CaseTemplate.key == template.key,\n                                                     CaseTemplate.status == v.TEMPLATE_PUBLISHED)).scalars():\n        old.status, old.retired_at = v.TEMPLATE_RETIRED, now\n    db.flush()\n    template.status, template.published_at = v.TEMPLATE_PUBLISHED, now\n    db.flush()\n    return template\n\n\ndef retire(db: Session, *, template: CaseTemplate) -> CaseTemplate:\n    if template.status != v.TEMPLATE_PUBLISHED:\n        raise TemplateError("NOT_PUBLISHED", "only a published template can be retired")\n    template.status, template.retired_at = v.TEMPLATE_RETIRED, datetime.now(timezone.utc)\n    db.flush()\n    return template\n\n\ndef document_types(template: CaseTemplate) -> set[str]:\n    return {r["doc_type"] for r in template.required_documents or []} | dsl.doc_types_of(template.rules or [])\n\n\n__all__ = ["TemplateError", "create", "document_types", "publish", "retire", "update_draft", "validate"]\n'),
    Op(path='backend/app/services/cases/vocabulary.py', kind='new', final_sha='9586028f1ae7ab2f561cc1d61066cf4b185460a0be4b25771fbcbaea621b9b74',
       variants=(),
       content='"""ARCH43-S1:cases-vocabulary. Mirrors the migration\'s CHECKs."""\n\nfrom __future__ import annotations\n\nfrom typing import Final\n\nTEMPLATE_DRAFT: Final = "DRAFT"\nTEMPLATE_PUBLISHED: Final = "PUBLISHED"\nTEMPLATE_RETIRED: Final = "RETIRED"\nASSEMBLY_ENTITY: Final = "ENTITY"\nASSEMBLY_BATCH: Final = "BATCH"\nASSEMBLY_MANUAL: Final = "MANUAL"\nASSEMBLY_KEYS: Final = (ASSEMBLY_ENTITY, ASSEMBLY_BATCH, ASSEMBLY_MANUAL)\nENTITY_KINDS: Final = ("PERSON", "ORGANIZATION", "ADDRESS", "ACCOUNT", "ASSET", "SHIPMENT")\nCASE_INCOMPLETE: Final = "INCOMPLETE"\nCASE_INCONSISTENT: Final = "INCONSISTENT"\nCASE_COMPLETE: Final = "COMPLETE"\nCASE_CLOSED: Final = "CLOSED"\nCASE_STATUSES: Final = (CASE_INCOMPLETE, CASE_INCONSISTENT, CASE_COMPLETE, CASE_CLOSED)\nSOURCE_AUTO: Final = "AUTO"\nSOURCE_MANUAL: Final = "MANUAL"\nSOURCE_REQUEST: Final = "REQUEST"\nREQUEST_OPEN: Final = "OPEN"\nREQUEST_FULFILLED: Final = "FULFILLED"\nREQUEST_EXPIRED: Final = "EXPIRED"\nREQUEST_REVOKED: Final = "REVOKED"\nJOB_ASSEMBLE: Final = "cases.assemble_document"\nEVENT_PACKET_SPLIT: Final = "trigger.packet.split"\nEVENT_CASE_COMPLETED: Final = "trigger.case.completed"\nEVENT_CASE_INCONSISTENT: Final = "trigger.case.inconsistent"\nMAX_REQUIRED: Final = 40\nMAX_RULES: Final = 60\n'),
