    Op(path='backend/app/services/packets/__init__.py', kind='new', final_sha='47d37322baba3d3a7b34f6f3c0f8b256eeeaff102ddc5e6800342ca3a1d070a6',
       variants=(),
       content='"""ARCH43-S1:packets — the Universal Packet Dicer (ARCH-43 Tranche 2).\n\nA scanned bundle (one PDF, many documents) is diced into child documents:\n\n  features.py         per-page boundary signals from what OCR already stored\n                      (ARCH-41 header-skeleton fingerprints, page-number\n                      resets, blank and separator sheets, classifier changes,\n                      document-number changes). Pure.\n  page_classifier.py  a deterministic per-page document type: ARCH-31\'s role\n                      rules plus ARCH-38\'s preset classifier hints. Pure.\n  model.py            the logistic boundary model. Fitted with scikit-learn by\n                      scripts/fit_packet_boundaries.py; SCORED with plain math,\n                      so detection runs on the LIGHT worker profile.\n  synthetic.py        labelled synthetic packets (fit and verification).\n  planner.py          probabilities -> a split plan (segments). Pure.\n  service.py          plans in the database: detect, reviewer correction,\n                      approve / reject, and apply (pikepdf, OCR profile).\n  lineage.py          parent/child queries and entity-mention supersession.\n  gate.py             capability.case_intelligence.\n"""\n'),
    Op(path='backend/app/services/packets/features.py', kind='new', final_sha='40176d5053a08fc5c5f9fc2fe4fbf38aedac8d34103595029bfa1c52ae362d7a',
       variants=(),
       content='"""ARCH43-S1:features — per-page boundary signals. Pure; no I/O.\n\nEvery signal is computed from text the OCR stage already stored\n(work_items.extraction_metadata["pages"]): nothing is re-OCR\'d.\n\nFor page i (1-based, i >= 2) against page i-1:\n\n  layout_change   1 - cosine of the ARCH-41 fingerprint of the two pages\'\n                  HEADER SKELETONS (first lines, digits masked). A new\n                  document usually brings a new letterhead.\n  page_one        page i says it is page 1 ("Page 1 of 3", "1/3", "- 1 -").\n  continues       page i says page k and page i-1 said k-1.\n  prev_last       page i-1 said "k of k": the previous document ended.\n  prev_blank      page i-1 was blank (a separator or a duplex back side).\n  blank           page i is blank (rarely the first page of anything).\n  separator       page i-1 was a separator sheet.\n  type_change     the page classifier\'s type changed (both confident).\n  title           page i carries a title phrase in its first lines.\n  number_change   a document number ("Invoice No", "PO No", ...) in the\n                  header differs from the previous page\'s.\n  number_same     the same document number continues.\n  text_jump       |log length ratio| of the two pages, capped at 1.\n"""\n\nfrom __future__ import annotations\n\nimport math\nimport re\nfrom dataclasses import dataclass, field\nfrom typing import Mapping, Optional, Sequence\n\nfrom app.services.extraction_memory import fingerprint as fp\nfrom app.services.packets import page_classifier as pc\n\nFEATURES: tuple[str, ...] = (\n    "layout_change", "page_one", "continues", "prev_last", "prev_blank", "blank", "separator",\n    "type_change", "title", "number_change", "number_same", "text_jump",\n)\nHEADER_LINES = 10\nBLANK_CHARS = 15\n\n_PAGE_OF = re.compile(r"\\bpage\\s*(\\d{1,3})\\s*(?:of|/)\\s*(\\d{1,3})\\b", re.I)\n_PAGE = re.compile(r"\\bpage\\s*(\\d{1,3})\\b", re.I)\n_SLASH = re.compile(r"^\\s*(\\d{1,3})\\s*/\\s*(\\d{1,3})\\s*$")\n_DASH = re.compile(r"^\\s*-\\s*(\\d{1,3})\\s*-\\s*$")\n_SEPARATOR = re.compile(r"\\b(separator\\s+sheet|document\\s+separator|patch\\s*(?:code|t)|batch\\s+separator|end\\s+of\\s+document)\\b", re.I)\n_NUMBER = re.compile(\n    r"\\b(invoice|inv|po|purchase\\s+order|order|receipt|grn|statement|policy|claim|contract|lease|reference|ref|"\n    r"document|doc|bill\\s+of\\s+lading|b/l|application|account|a/c)\\s*(?:no|number|num|#|id)\\.?\\s*[:#.]?\\s*"\n    r"([A-Z0-9][A-Z0-9\\-/]{2,})", re.I)\n\n\n@dataclass\nclass PageFacts:\n    text: str\n    blank: bool\n    number: Optional[tuple[int, Optional[int]]]\n    separator: bool\n    cls: pc.PageClass\n    signature: Optional[list[float]]\n    doc_numbers: dict[str, str] = field(default_factory=dict)\n    length: int = 0\n\n\ndef _lines(text: str) -> list[str]:\n    return [line.strip() for line in (text or "").splitlines() if line.strip()]\n\n\ndef page_number(text: str) -> Optional[tuple[int, Optional[int]]]:\n    lines = _lines(text)\n    edge = lines[:3] + lines[-3:]\n    for line in edge:\n        m = _PAGE_OF.search(line)\n        if m:\n            k, n = int(m.group(1)), int(m.group(2))\n            if 1 <= k <= n:\n                return k, n\n    for line in edge:\n        m = _SLASH.match(line)\n        if m and 1 <= int(m.group(1)) <= int(m.group(2)):\n            return int(m.group(1)), int(m.group(2))\n        m = _PAGE.search(line) or _DASH.match(line)\n        if m and int(m.group(1)) >= 1:\n            return int(m.group(1)), None\n    return None\n\n\ndef _doc_numbers(text: str) -> dict[str, str]:\n    found: dict[str, str] = {}\n    for line in _lines(text)[:15]:\n        for m in _NUMBER.finditer(line):\n            label = re.sub(r"\\s+", " ", m.group(1).lower())\n            found.setdefault(label, m.group(2).upper().strip("-/"))\n    return found\n\n\ndef facts(text: str, extra_hints: Optional[Mapping[str, Sequence[str]]] = None) -> PageFacts:\n    body = text or ""\n    alnum = sum(ch.isalnum() for ch in body)\n    header = "\\n".join(_lines(body)[:HEADER_LINES])\n    return PageFacts(\n        text=body,\n        blank=alnum < BLANK_CHARS,\n        number=page_number(body),\n        separator=bool(_SEPARATOR.search(body)) and alnum < 400,\n        cls=pc.classify_page(body, extra_hints),\n        signature=fp.signature(header),\n        doc_numbers=_doc_numbers(body),\n        length=alnum,\n    )\n\n\ndef pair_features(prev: PageFacts, cur: PageFacts, prev_content: Optional[PageFacts] = None) -> dict[str, float]:\n    """Features of the boundary BEFORE `cur`. `prev_content` is the last\n    non-blank page before cur (layout and type compare against content, not a\n    blank separator)."""\n    ref = prev_content or prev\n    layout = 0.0\n    if cur.signature is not None and ref.signature is not None:\n        layout = max(0.0, 1.0 - fp.cosine(cur.signature, ref.signature))\n    elif not cur.blank and ref.signature is None:\n        layout = 0.5\n    continues = 0.0\n    if cur.number and ref.number and cur.number[0] == ref.number[0] + 1:\n        if cur.number[1] is None or ref.number[1] is None or cur.number[1] == ref.number[1]:\n            continues = 1.0\n    type_change = 0.0\n    a, b = ref.cls, cur.cls\n    if a.doc_type != pc.OTHER and b.doc_type != pc.OTHER and a.doc_type != b.doc_type:\n        type_change = min(1.0, (a.confidence + b.confidence) / 2 + 0.25)\n    shared = set(ref.doc_numbers) & set(cur.doc_numbers)\n    number_change = 1.0 if any(ref.doc_numbers[k] != cur.doc_numbers[k] for k in shared) else 0.0\n    number_same = 1.0 if any(ref.doc_numbers[k] == cur.doc_numbers[k] for k in shared) else 0.0\n    jump = abs(math.log((cur.length + 1) / (ref.length + 1)))\n    return {\n        "layout_change": round(layout, 4),\n        "page_one": 1.0 if cur.number and cur.number[0] == 1 else 0.0,\n        "continues": continues,\n        "prev_last": 1.0 if ref.number and ref.number[1] and ref.number[0] == ref.number[1] else 0.0,\n        "prev_blank": 1.0 if prev.blank else 0.0,\n        "blank": 1.0 if cur.blank else 0.0,\n        "separator": 1.0 if prev.separator else 0.0,\n        "type_change": round(type_change, 4),\n        "title": 1.0 if cur.cls.title_hit else 0.0,\n        "number_change": number_change,\n        "number_same": number_same,\n        "text_jump": round(min(1.0, jump / 3.0), 4),\n    }\n\n\ndef packet_features(texts: Sequence[str], extra_hints=None) -> tuple[list[PageFacts], list[Optional[dict[str, float]]]]:\n    """Facts per page and the boundary features before each page (None for page 1)."""\n    pages = [facts(t, extra_hints) for t in texts]\n    out: list[Optional[dict[str, float]]] = [None]\n    last_content: Optional[PageFacts] = pages[0] if pages and not pages[0].blank else None\n    for i in range(1, len(pages)):\n        out.append(pair_features(pages[i - 1], pages[i], last_content))\n        if not pages[i].blank and not pages[i].separator:\n            last_content = pages[i]\n    return pages, out\n\n\ndef vector(features: Mapping[str, float]) -> list[float]:\n    return [float(features[name]) for name in FEATURES]\n\n\n__all__ = ["FEATURES", "PageFacts", "facts", "packet_features", "page_number", "pair_features", "vector"]\n'),
    Op(path='backend/app/services/packets/gate.py', kind='new', final_sha='0747b7fcf4b28887800801505d46c595fbbc81eda7aae9b2fb97f1eebc3d4b5b',
       variants=(),
       content='"""ARCH43-S1:gate — may the packet dicer run for this organization?"""\n\nfrom __future__ import annotations\n\nimport logging\nimport uuid\n\nfrom sqlalchemy.orm import Session\n\nlogger = logging.getLogger("app.services.packets.gate")\n\n\ndef capability_held(db: Session, organization_id: uuid.UUID) -> bool:\n    from app.api import capability_gate\n    from app.core import entitlements\n\n    try:\n        return capability_gate.has_capability(\n            db, organization_id=organization_id, capability_key=entitlements.CASE_INTELLIGENCE_CAPABILITY)\n    except Exception:  # noqa: BLE001 - an unreadable plan is "not held", never a crash in the pipeline\n        logger.exception("packets.capability_unreadable")\n        return False\n\n\ndef organization_of(db: Session, work_item: object) -> uuid.UUID:\n    from app.services.extraction_memory.gate import organization_of as _org\n\n    return _org(db, work_item)\n'),
    Op(path='backend/app/services/packets/lineage.py', kind='new', final_sha='7243c571660db3b3755d5a3458925e3a3fa97e123e28c7ba85fa38de454e27d0',
       variants=(),
       content='"""ARCH43-S1:lineage — parents, children and mention supersession.\n\nRoadmap adjustment 4: ARCH-42 resolved the PACKET\'s fields into entity\nmentions before anyone knew it was a packet. When the packet is split, those\nmentions are SUPERSEDED (stamped with the split that replaced them), never\ndeleted: the evidence stays auditable, Entity 360 stops counting it, and the\nchildren -- each enriched on its own -- are resolved into their own mentions\nby the ordinary ARCH-42 path. resolver.resolve_work_item refuses to\nre-resolve a split parent, so the nightly sweep cannot resurrect them.\n"""\n\nfrom __future__ import annotations\n\nimport uuid\nfrom datetime import datetime, timezone\nfrom typing import Any, Optional\n\nfrom sqlalchemy import exists, select, update\nfrom sqlalchemy.orm import Session\n\nfrom app.models.packets import PacketSplit, PacketSplitSegment\nfrom app.services.packets import vocabulary as v\n\n\ndef is_split_parent(db: Session, work_item_id: uuid.UUID) -> bool:\n    return bool(db.execute(select(exists().where(\n        PacketSplit.work_item_id == work_item_id, PacketSplit.status == v.STATUS_APPLIED))).scalar())\n\n\ndef supersede_parent_mentions(db: Session, *, split: PacketSplit) -> int:\n    from app.models.entity_graph import EntityMention\n\n    result = db.execute(\n        update(EntityMention)\n        .where(EntityMention.work_item_id == split.work_item_id, EntityMention.workspace_id == split.workspace_id,\n               EntityMention.superseded_at.is_(None))\n        .values(superseded_at=datetime.now(timezone.utc), superseded_by_split_id=split.id)\n        .execution_options(synchronize_session=False)\n    )\n    return int(result.rowcount or 0)\n\n\ndef lineage_of(db: Session, *, workspace_id: uuid.UUID, work_item_id: uuid.UUID) -> dict[str, Any]:\n    from app.models.work_item import WorkItem\n\n    item = db.execute(select(WorkItem).where(WorkItem.id == work_item_id, WorkItem.workspace_id == workspace_id)).scalar_one_or_none()\n    if item is None:\n        raise LookupError("work item not found")\n    parent: Optional[WorkItem] = db.get(WorkItem, item.parent_work_item_id) if item.parent_work_item_id else None\n    split = db.execute(select(PacketSplit).where(PacketSplit.work_item_id == work_item_id,\n                                                 PacketSplit.status.in_(v.LIVE_STATUSES))).scalar_one_or_none()\n    children = []\n    if split is not None:\n        rows = db.execute(select(PacketSplitSegment, WorkItem).outerjoin(\n            WorkItem, WorkItem.id == PacketSplitSegment.child_work_item_id).where(\n            PacketSplitSegment.split_id == split.id).order_by(PacketSplitSegment.ordinal)).all()\n        children = [{"ordinal": s.ordinal, "page_start": s.page_start, "page_end": s.page_end,\n                     "document_type": s.document_type, "work_item_id": w.id if w else None,\n                     "original_filename": w.original_filename if w else None,\n                     "pipeline_stage": w.pipeline_stage if w else None} for s, w in rows]\n    return {\n        "work_item_id": item.id,\n        "parent": None if parent is None else {"work_item_id": parent.id, "original_filename": parent.original_filename,\n                                               "page_start": item.parent_page_start, "page_end": item.parent_page_end},\n        "split": None if split is None else {"split_id": split.id, "status": split.status},\n        "children": children,\n    }\n\n\n__all__ = ["is_split_parent", "lineage_of", "supersede_parent_mentions"]\n'),
    Op(path='backend/app/services/packets/model.py', kind='new', final_sha='95595db7ab26d18aec53f1953615ecd9705b14e5f317cab8756819f9f5cb77d9',
       variants=(),
       content='"""ARCH43-S1:model — the logistic boundary model, scored with plain math.\n\nThe coefficients below are FITTED, not hand-set: scikit-learn\'s\nLogisticRegression on the labelled synthetic packets (synthetic.TRAIN_SEEDS)\nby `python scripts/fit_packet_boundaries.py --write`, which rewrites the block\nbetween the markers. verify_arch43 T4 refits and checks the shipped numbers\nreproduce, and measures precision/recall on held-out packets.\n\nScoring needs no scikit-learn at runtime (the LIGHT worker profile imports\nno model libraries): p = 1 / (1 + exp(-(b + w . x))).\n"""\n\nfrom __future__ import annotations\n\nimport math\nfrom typing import Mapping, Sequence\n\nfrom app.services.packets.features import FEATURES\n\n# --- fitted: begin (generated by scripts/fit_packet_boundaries.py) ---\nMODEL_VERSION = "pb-1"\nINTERCEPT = -3.704565\nCOEF: dict[str, float] = {\n    "layout_change": 2.796494,\n    "page_one": 5.452208,\n    "continues": -4.794162,\n    "prev_last": 5.072901,\n    "prev_blank": 0.236898,\n    "blank": 0.0,\n    "separator": 3.372166,\n    "type_change": 0.826542,\n    "title": 1.043692,\n    "number_change": 0.915124,\n    "number_same": -3.430563,\n    "text_jump": 1.931622,\n}\nFIT_STATS: dict[str, float] = {"held_out_precision": 0.9754, "held_out_recall": 0.8982, "positives": 2976, "rows": 6309}\n# --- fitted: end ---\n\n\ndef probability(features: Mapping[str, float]) -> float:\n    z = INTERCEPT + sum(COEF[name] * float(features[name]) for name in FEATURES)\n    if z >= 0:\n        return 1.0 / (1.0 + math.exp(-z))\n    e = math.exp(z)\n    return e / (1.0 + e)\n\n\ndef probabilities(pair_features: Sequence) -> list[float]:\n    """Boundary probability before each page; page 1 always starts a document."""\n    return [1.0 if f is None else probability(f) for f in pair_features]\n\n\n__all__ = ["COEF", "FIT_STATS", "INTERCEPT", "MODEL_VERSION", "probabilities", "probability"]\n'),
    Op(path='backend/app/services/packets/page_classifier.py', kind='new', final_sha='d723e3c19514bd949c4f45fd474e58ffdd33a4801989d0c42b897ca262d139b4',
       variants=(),
       content='"""ARCH43-S1:page-classifier — a deterministic document type for ONE page.\n\nThe packet dicer needs "did the document type change between these two\npages?", which needs a type per page. Nothing in the platform produced one:\nARCH-31\'s role classifier knows seven procurement roles, and ARCH-38\'s preset\n`classifier_hints` were stored but read by nothing except ARCH-42\'s prompt\nbuilder. This module combines both, deterministically (the same page always\ngets the same type, and the evidence is a phrase a reviewer can see), with no\nmodel and no external call.\n\nPRESET_HINTS is a copy of the eleven ARCH-38 platform presets\' hints;\nverify_arch43 T5 asserts it equals the migration\'s list, so the two cannot\ndrift. Tenant presets\' hints can be passed in as `extra_hints`.\n"""\n\nfrom __future__ import annotations\n\nimport re\nfrom dataclasses import dataclass\nfrom typing import Mapping, Optional, Sequence\n\nfrom app.services.procurement_matching import role_classifier as rc\n\nTITLE_WINDOW = 300\nHINT_WEIGHT = 0.6\nTITLE_MULTIPLIER = 2.0\nMIN_SCORE = 0.6\nOTHER = "other"\n\n#: ARCH43-S1:preset-hints. document_type -> ARCH-38 classifier_hints.\nPRESET_HINTS: dict[str, tuple[str, ...]] = {\n    "resume": ("curriculum vitae", "resume", "work experience", "education"),\n    "offer_letter": ("offer of employment", "we are pleased to offer", "start date"),\n    "intake_form": ("patient intake", "date of birth", "presenting complaint"),\n    "discharge_summary": ("discharge summary", "date of admission", "follow-up"),\n    "nda": ("non-disclosure", "confidential information", "receiving party"),\n    "msa": ("master services agreement", "statement of work", "limitation of liability"),\n    "lease": ("lease", "landlord", "tenant", "demised premises"),\n    "bill_of_lading": ("bill of lading", "shipper", "consignee", "port of discharge"),\n    "customs_manifest": ("customs", "manifest", "hs code", "country of origin"),\n    "passport": ("passport", "machine readable zone", "date of expiry"),\n    "india_id_card": ("aadhaar", "permanent account number", "unique identification"),\n}\n\n_ROLE_TYPES = {role: role.lower() for role in rc.ROLES if role != rc.ROLE_OTHER}\n\n\ndef _compile(hints: Mapping[str, Sequence[str]]) -> list[tuple[str, re.Pattern[str]]]:\n    out = []\n    for doc_type, phrases in hints.items():\n        for phrase in phrases:\n            out.append((doc_type, re.compile(r"\\b" + re.escape(phrase.lower()) + r"\\b")))\n    return out\n\n\n_PRESET_PATTERNS = _compile(PRESET_HINTS)\n\n\n@dataclass(frozen=True)\nclass PageClass:\n    doc_type: str\n    confidence: float\n    title_hit: bool\n\n\ndef classify_page(text: Optional[str], extra_hints: Optional[Mapping[str, Sequence[str]]] = None) -> PageClass:\n    body = (text or "").strip()\n    if not body:\n        return PageClass(OTHER, 0.0, False)\n    lower = body.lower()\n    scores: dict[str, float] = {}\n    titles: dict[str, bool] = {}\n    verdict = rc.classify(body)\n    for role, score in verdict.ranking:\n        if role in _ROLE_TYPES:\n            scores[_ROLE_TYPES[role]] = scores.get(_ROLE_TYPES[role], 0.0) + float(score)\n    for signal in verdict.signals:\n        if signal.role in _ROLE_TYPES and signal.char_start < TITLE_WINDOW:\n            titles[_ROLE_TYPES[signal.role]] = True\n    patterns = _PRESET_PATTERNS + (_compile(extra_hints) if extra_hints else [])\n    for doc_type, pattern in patterns:\n        match = pattern.search(lower)\n        if match is None:\n            continue\n        weight = HINT_WEIGHT\n        if match.start() < TITLE_WINDOW:\n            weight *= TITLE_MULTIPLIER\n            titles[doc_type] = True\n        scores[doc_type] = scores.get(doc_type, 0.0) + weight\n    total = sum(scores.values())\n    if total <= 0:\n        return PageClass(OTHER, 0.0, False)\n    leader = sorted(scores.items(), key=lambda kv: (-kv[1], kv[0]))[0]\n    if leader[1] < MIN_SCORE:\n        return PageClass(OTHER, round(leader[1] / total, 4), False)\n    return PageClass(leader[0], round(leader[1] / total, 4), bool(titles.get(leader[0])))\n\n\n__all__ = ["PRESET_HINTS", "PageClass", "classify_page", "OTHER"]\n'),
    Op(path='backend/app/services/packets/planner.py', kind='new', final_sha='1634fa01098dd013abe84777a4d9d8aed40522f36afa7955c20f138a1d71eb1b',
       variants=(),
       content='"""ARCH43-S1:planner — boundary probabilities -> a split plan. Pure.\n\nA page starts a new document when its probability reaches the threshold,\nexcept that a blank page or a separator sheet never starts one (it stays with\nthe document before it, as a duplex back side or a sheet between documents\nwould). Every plan covers every page exactly once, in order: the segments are\ncontiguous by construction, and the database\'s exclusion constraint refuses\noverlap independently.\n"""\n\nfrom __future__ import annotations\n\nfrom collections import Counter\nfrom dataclasses import dataclass\nfrom typing import Mapping, Optional, Sequence\n\nfrom app.services.packets import features as ft\nfrom app.services.packets import model\nfrom app.services.packets import page_classifier as pc\nfrom app.services.packets import vocabulary as v\n\n\nclass PlanError(ValueError):\n    """A boundary list that is not a plan (out of range, duplicated, unordered)."""\n\n\n@dataclass(frozen=True)\nclass Segment:\n    ordinal: int\n    page_start: int\n    page_end: int\n    document_type: Optional[str]\n    confidence: float\n    title: Optional[str]\n\n\n@dataclass(frozen=True)\nclass Plan:\n    page_count: int\n    probabilities: list[float]\n    features: list[Optional[dict]]\n    page_types: list[str]\n    segments: list[Segment]\n    certainty: float\n    threshold: float\n\n    @property\n    def boundaries(self) -> list[int]:\n        return [s.page_start for s in self.segments[1:]]\n\n    def page_scores(self) -> list[dict]:\n        return [{"page": i + 1, "p": round(p, 4), "doc_type": self.page_types[i], "features": self.features[i]}\n                for i, p in enumerate(self.probabilities)]\n\n\ndef _title(text: str) -> Optional[str]:\n    for line in (text or "").splitlines():\n        line = line.strip()\n        if len(line) >= 3 and any(ch.isalpha() for ch in line):\n            return line[:200]\n    return None\n\n\ndef segments_for(boundaries: Sequence[int], page_count: int, facts: Sequence[ft.PageFacts],\n                 probabilities: Sequence[float]) -> list[Segment]:\n    starts = [1, *boundaries]\n    ends = [b - 1 for b in boundaries] + [page_count]\n    out: list[Segment] = []\n    for ordinal, (start, end) in enumerate(zip(starts, ends)):\n        types = Counter(facts[i].cls.doc_type for i in range(start - 1, end) if facts[i].cls.doc_type != pc.OTHER)\n        first = facts[start - 1].cls.doc_type\n        doc_type = first if first != pc.OTHER else (types.most_common(1)[0][0] if types else None)\n        out.append(Segment(ordinal, start, end, doc_type, round(float(probabilities[start - 1]), 4),\n                           _title(facts[start - 1].text)))\n    return out\n\n\ndef validate_boundaries(boundaries: Sequence[int], page_count: int) -> list[int]:\n    try:\n        values = [int(b) for b in boundaries]\n    except (TypeError, ValueError) as exc:\n        raise PlanError("boundaries must be page numbers") from exc\n    if values != sorted(values):\n        raise PlanError("boundaries must be in ascending page order")\n    if len(set(values)) != len(values):\n        raise PlanError("a page can start only one document")\n    if values and (values[0] < 2 or values[-1] > page_count):\n        raise PlanError(f"a boundary must be a page between 2 and {page_count}")\n    return values\n\n\ndef plan(texts: Sequence[str], *, threshold: float = v.DEFAULT_THRESHOLD,\n         extra_hints: Optional[Mapping] = None) -> Plan:\n    if not texts:\n        raise PlanError("the document has no pages")\n    if len(texts) > v.MAX_PAGES:\n        raise PlanError(f"packets longer than {v.MAX_PAGES} pages are not diced")\n    facts, pair = ft.packet_features(texts, extra_hints)\n    probs = model.probabilities(pair)\n    boundaries = [i + 1 for i in range(1, len(texts))\n                  if probs[i] >= threshold and not facts[i].blank and not facts[i].separator]\n    certainty = min((max(p, 1.0 - p) for p in probs[1:]), default=1.0)\n    return Plan(page_count=len(texts), probabilities=probs, features=pair,\n                page_types=[f.cls.doc_type for f in facts],\n                segments=segments_for(boundaries, len(texts), facts, probs),\n                certainty=round(certainty, 4), threshold=threshold)\n\n\ndef evaluate(corpus: Sequence[tuple[Sequence[str], set[int]]], threshold: float = v.DEFAULT_THRESHOLD,\n             predictor=None) -> dict[str, float]:\n    """Boundary precision/recall (page 1 excluded) over labelled packets."""\n    tp = fp = fn = 0\n    for texts, truth in corpus:\n        predicted = set(predictor(texts) if predictor else plan(texts, threshold=threshold).boundaries)\n        true = {s for s in truth if s != 1}\n        tp += len(predicted & true)\n        fp += len(predicted - true)\n        fn += len(true - predicted)\n    precision = tp / max(1, tp + fp)\n    recall = tp / max(1, tp + fn)\n    return {"precision": round(precision, 4), "recall": round(recall, 4),\n            "f1": round(2 * precision * recall / max(1e-9, precision + recall), 4),\n            "boundaries": tp + fn, "packets": len(corpus)}\n\n\ndef page_number_baseline(texts: Sequence[str]) -> list[int]:\n    """The heuristic most tools ship: split where a page says it is page 1."""\n    return [i + 1 for i, t in enumerate(texts) if i > 0 and (ft.page_number(t) or (0,))[0] == 1]\n\n\n__all__ = ["Plan", "PlanError", "Segment", "evaluate", "page_number_baseline", "plan", "segments_for",\n           "validate_boundaries"]\n'),
    Op(path='backend/app/services/packets/service.py', kind='new', final_sha='f84e0c8a6eec066adc921636268f07651a5bae42f2400700cec39496b7b85f12',
       variants=(),
       content='"""ARCH43-S1:service — split plans in the database.\n\ndetect()   read the pages OCR stored, plan, and record a PROPOSED plan (or\n           SINGLE when the packet is one document). No PDF engine.\nreplan()   the reviewer\'s correction: a new boundary list replaces the\n           segments (validated here; the exclusion constraint and the range\n           trigger refuse a bad plan independently).\napprove()  optionally with corrected boundaries; enqueues packets.apply_split.\nreject()   keep the packet as one document.\napply()    the job body (OCR worker profile): pikepdf writes one PDF per\n           segment, each goes through the SAME validation and intake as an\n           upload (tenant-scoped storage key, uploaded_files row, audit,\n           trigger.work_item.created), the parent\'s per-page OCR is COPIED to\n           the child (no page is OCR\'d or billed twice), the child moves to\n           EXTRACTED and is enriched like any document, and the parent\'s\n           entity mentions are superseded. The original is retained.\n"""\n\nfrom __future__ import annotations\n\nimport io\nimport logging\nimport uuid\nfrom datetime import datetime, timezone\nfrom decimal import Decimal\nfrom pathlib import PurePath\nfrom typing import Any, Optional, Sequence\n\nfrom sqlalchemy import delete, select\nfrom sqlalchemy.orm import Session\n\nfrom app.models.audit_log import AuditAction, AuditOutcome, AuditResourceType\nfrom app.models.packets import PacketSplit, PacketSplitSegment\nfrom app.models.work_item import WorkItem\nfrom app.services import audit_service\nfrom app.services.packets import gate, lineage, planner\nfrom app.services.packets import model as boundary_model\nfrom app.services.packets import vocabulary as v\n\nlogger = logging.getLogger("app.services.packets.service")\n\n\nclass PacketError(ValueError):\n    def __init__(self, code: str, message: str) -> None:\n        super().__init__(message)\n        self.code = code\n\n\ndef now() -> datetime:\n    return datetime.now(timezone.utc)\n\n\ndef page_texts(work_item: WorkItem) -> list[str]:\n    meta = work_item.extraction_metadata or {}\n    pages = meta.get("pages") if isinstance(meta, dict) else None\n    if isinstance(pages, list) and pages and isinstance(pages[0], dict):\n        ordered = sorted(pages, key=lambda p: int(p.get("page_number") or 0))\n        return [str(p.get("text") or "") for p in ordered]\n    text = work_item.extracted_text or ""\n    return text.split("\\f") if "\\f" in text else ([text] if text else [])\n\n\ndef _tenant_hints(db: Session, organization_id: uuid.UUID) -> dict[str, list[str]]:\n    from app.models.ingestion import DocumentSchemaPreset\n\n    rows = db.execute(select(DocumentSchemaPreset.document_type, DocumentSchemaPreset.classifier_hints).where(\n        DocumentSchemaPreset.organization_id == organization_id)).all()\n    return {doc_type: [str(h) for h in (hints or []) if isinstance(h, str)] for doc_type, hints in rows if hints}\n\n\ndef _audit(db: Session, split: PacketSplit, operation: str, actor: Optional[uuid.UUID], **extra: Any) -> None:\n    audit_service.record(\n        db, organization_id=split.organization_id, workspace_id=split.workspace_id, actor_id=actor,\n        resource_type=AuditResourceType.WORKSPACE, resource_id=split.workspace_id, action=AuditAction.UPDATED,\n        outcome=AuditOutcome.ALLOWED,\n        details={"packet_split": {"operation": operation, "split_id": str(split.id),\n                                  "work_item_id": str(split.work_item_id), "status": split.status, **extra}},\n    )\n\n\ndef _write_segments(db: Session, split: PacketSplit, segments: Sequence[planner.Segment]) -> None:\n    db.execute(delete(PacketSplitSegment).where(PacketSplitSegment.split_id == split.id))\n    db.flush()\n    for s in segments:\n        db.add(PacketSplitSegment(id=uuid.uuid4(), split_id=split.id, workspace_id=split.workspace_id, ordinal=s.ordinal,\n                                  page_start=s.page_start, page_end=s.page_end, document_type=s.document_type,\n                                  confidence=Decimal(str(round(min(1.0, max(0.0, s.confidence)), 4))), title=s.title))\n    db.flush()\n\n\ndef live_split(db: Session, work_item_id: uuid.UUID) -> Optional[PacketSplit]:\n    return db.execute(select(PacketSplit).where(PacketSplit.work_item_id == work_item_id,\n                                                PacketSplit.status.in_(v.LIVE_STATUSES))).scalar_one_or_none()\n\n\ndef segments_of(db: Session, split_id: uuid.UUID) -> list[PacketSplitSegment]:\n    return list(db.execute(select(PacketSplitSegment).where(PacketSplitSegment.split_id == split_id)\n                           .order_by(PacketSplitSegment.ordinal)).scalars())\n\n\ndef detect(db: Session, *, work_item: WorkItem, actor_user_id: Optional[uuid.UUID] = None,\n           force: bool = False) -> PacketSplit:\n    organization_id = gate.organization_of(db, work_item)\n    existing = live_split(db, work_item.id)\n    if existing is not None:\n        if existing.status in v.DECIDED_STATUSES:\n            return existing  # a reviewer decided; detection never overrides a person\n        if not force and existing.model_version == boundary_model.MODEL_VERSION and existing.source == v.SOURCE_MODEL:\n            return existing  # idempotent: the same pages give the same plan\n        existing.status = v.STATUS_SUPERSEDED\n        existing.updated_at = now()\n        db.flush()\n    texts = page_texts(work_item)\n    if not texts:\n        raise PacketError("NO_PAGES", "This document has no extracted pages to split yet.")\n    try:\n        result = planner.plan(texts, extra_hints=_tenant_hints(db, organization_id))\n    except planner.PlanError as exc:\n        raise PacketError("PLAN_REFUSED", str(exc)) from exc\n    split = PacketSplit(\n        id=uuid.uuid4(), organization_id=organization_id, workspace_id=work_item.workspace_id, work_item_id=work_item.id,\n        status=v.STATUS_PROPOSED if len(result.segments) > 1 else v.STATUS_SINGLE, source=v.SOURCE_MODEL,\n        page_count=result.page_count, model_version=boundary_model.MODEL_VERSION,\n        threshold=Decimal(str(result.threshold)), certainty=Decimal(str(result.certainty)),\n        page_scores=result.page_scores(), created_by_user_id=actor_user_id,\n    )\n    db.add(split)\n    db.flush()\n    _write_segments(db, split, result.segments)\n    _audit(db, split, "detect", actor_user_id, segments=len(result.segments), certainty=float(result.certainty))\n    return split\n\n\ndef _stored_facts(split: PacketSplit) -> tuple[list, list[float]]:\n    """Rebuild just enough per-page facts from page_scores to name segments."""\n    from types import SimpleNamespace\n\n    scores = sorted(split.page_scores or [], key=lambda s: s["page"])\n    facts = [SimpleNamespace(cls=SimpleNamespace(doc_type=s.get("doc_type") or "other"), text="") for s in scores]\n    return facts, [float(s.get("p") or 0.0) for s in scores]\n\n\ndef replan(db: Session, *, split: PacketSplit, boundaries: Sequence[int], actor_user_id: uuid.UUID) -> PacketSplit:\n    if split.status not in (v.STATUS_PROPOSED, v.STATUS_SINGLE):\n        raise PacketError("NOT_EDITABLE", f"A {split.status.lower()} plan cannot be changed.")\n    try:\n        values = planner.validate_boundaries(boundaries, split.page_count)\n    except planner.PlanError as exc:\n        raise PacketError("INVALID_BOUNDARIES", str(exc)) from exc\n    facts, probs = _stored_facts(split)\n    if len(facts) != split.page_count:\n        facts = [type("F", (), {"cls": type("C", (), {"doc_type": "other"})(), "text": ""})() for _ in range(split.page_count)]\n        probs = [1.0] + [0.0] * (split.page_count - 1)\n    old_titles = {s.page_start: s.title for s in segments_of(db, split.id)}\n    segments = planner.segments_for(values, split.page_count, facts, probs)\n    segments = [planner.Segment(s.ordinal, s.page_start, s.page_end, None if s.document_type == "other" else s.document_type,\n                                s.confidence, old_titles.get(s.page_start)) for s in segments]\n    _write_segments(db, split, segments)\n    split.source = v.SOURCE_REVIEWER\n    split.status = v.STATUS_PROPOSED if len(segments) > 1 else v.STATUS_SINGLE\n    split.updated_at = now()\n    db.flush()\n    _audit(db, split, "replan", actor_user_id, boundaries=values)\n    return split\n\n\ndef approve(db: Session, *, split: PacketSplit, actor_user_id: uuid.UUID,\n            boundaries: Optional[Sequence[int]] = None) -> PacketSplit:\n    from app.services import job_service\n\n    if boundaries is not None:\n        replan(db, split=split, boundaries=boundaries, actor_user_id=actor_user_id)\n    if split.status != v.STATUS_PROPOSED:\n        raise PacketError("NOT_APPROVABLE", "Only a proposed plan with at least two documents can be approved.")\n    split.status, split.decided_at, split.decided_by_user_id, split.updated_at = v.STATUS_APPROVED, now(), actor_user_id, now()\n    db.flush()\n    job_service.enqueue(db, job_type=v.JOB_APPLY, organization_id=split.organization_id,\n                        payload={"split_id": str(split.id), "workspace_id": str(split.workspace_id)},\n                        idempotency_key=f"{v.JOB_APPLY}:{split.id}")\n    _audit(db, split, "approve", actor_user_id, segments=len(segments_of(db, split.id)))\n    return split\n\n\ndef reject(db: Session, *, split: PacketSplit, actor_user_id: uuid.UUID) -> PacketSplit:\n    if split.status not in (v.STATUS_PROPOSED, v.STATUS_SINGLE):\n        raise PacketError("NOT_REJECTABLE", f"A {split.status.lower()} plan cannot be rejected.")\n    split.status, split.decided_at, split.decided_by_user_id, split.updated_at = v.STATUS_REJECTED, now(), actor_user_id, now()\n    db.flush()\n    _audit(db, split, "reject", actor_user_id)\n    return split\n\n\ndef _child_pdf(source: Any, start: int, end: int) -> bytes:\n    import pikepdf\n\n    out = pikepdf.Pdf.new()\n    for index in range(start - 1, end):\n        out.pages.append(source.pages[index])\n    buffer = io.BytesIO()\n    out.save(buffer)\n    return buffer.getvalue()\n\n\ndef _child_name(parent: WorkItem, segment: PacketSplitSegment) -> str:\n    stem = PurePath(parent.original_filename or "packet.pdf").stem[:120]\n    kind = f" {segment.document_type}" if segment.document_type else ""\n    return f"{stem} - part {segment.ordinal + 1}{kind} (pages {segment.page_start}-{segment.page_end}).pdf"[:255]\n\n\ndef _copy_ocr(parent: WorkItem, child: WorkItem, split: PacketSplit, segment: PacketSplitSegment) -> None:\n    meta = parent.extraction_metadata if isinstance(parent.extraction_metadata, dict) else {}\n    pages = sorted([p for p in (meta.get("pages") or []) if isinstance(p, dict)], key=lambda p: int(p.get("page_number") or 0))\n    sliced = []\n    for new_number, page in enumerate(pages[segment.page_start - 1:segment.page_end], start=1):\n        sliced.append({**page, "page_number": new_number, "source_page_number": page.get("page_number")})\n    child.extracted_text = "\\n".join(str(p.get("text") or "") for p in sliced if p.get("text"))\n    child.page_count = segment.page_end - segment.page_start + 1\n    child.extraction_metadata = {\n        "provider": meta.get("provider"), "model": meta.get("model"), "pages": sliced,\n        "billable_pages": 0, "mean_confidence": meta.get("mean_confidence"),\n        "packet_split": {"split_id": str(split.id), "parent_work_item_id": str(parent.id),\n                         "page_start": segment.page_start, "page_end": segment.page_end},\n    }\n\n\ndef apply(db: Session, *, split_id: uuid.UUID) -> dict[str, Any]:\n    """The packets.apply_split job body. The caller commits."""\n    import pikepdf\n\n    from app.core.config import settings\n    from app.core.storage import get_storage_driver\n    from app.services import document_intake_service, file_validation_service, job_service\n    from app.services.pipeline_state import PipelineStage, transition_by_id\n\n    split = db.execute(select(PacketSplit).where(PacketSplit.id == split_id).with_for_update()).scalar_one_or_none()\n    if split is None:\n        return {"applied": False, "reason": "plan no longer exists"}\n    if split.status == v.STATUS_APPLIED:\n        return {"applied": True, "children": 0, "reason": "already applied"}\n    if split.status not in (v.STATUS_APPROVED, v.STATUS_APPLYING):\n        return {"applied": False, "reason": f"plan is {split.status}"}\n    parent = db.execute(select(WorkItem).where(WorkItem.id == split.work_item_id,\n                                               WorkItem.workspace_id == split.workspace_id)).scalar_one()\n    if (parent.file_type or "").split(";")[0].strip().lower() != v.PDF_MIME:\n        raise PacketError("NOT_PDF", "Only PDF packets can be split.")\n    split.status = v.STATUS_APPLYING\n    db.flush()\n    blob = get_storage_driver().get(parent.stored_filename)\n    created: list[uuid.UUID] = []\n    with pikepdf.open(io.BytesIO(blob)) as source:\n        if len(source.pages) != split.page_count:\n            raise PacketError("PAGE_MISMATCH", f"the PDF has {len(source.pages)} pages; the plan has {split.page_count}")\n        for segment in segments_of(db, split.id):\n            if segment.child_work_item_id is not None:\n                continue  # a retry after a partial apply\n            data = _child_pdf(source, segment.page_start, segment.page_end)\n            validated = file_validation_service.validate_spooled(\n                io.BytesIO(data), len(data), declared_mime=v.PDF_MIME, original_filename=_child_name(parent, segment),\n                allowed_mimes=[v.PDF_MIME], max_pages=settings.MAX_DOCUMENT_PAGES,\n                scrub_metadata=settings.SCRUB_UPLOAD_METADATA)\n            with validated:\n                result = document_intake_service.ingest_validated(\n                    db, validated, organization_id=split.organization_id, workspace_id=split.workspace_id,\n                    uploader_id=split.decided_by_user_id or parent.created_by_user_id, enqueue_extraction=False)\n            child = result.work_item\n            child.parent_work_item_id = parent.id\n            child.parent_page_start, child.parent_page_end = segment.page_start, segment.page_end\n            _copy_ocr(parent, child, split, segment)\n            db.flush([child])\n            for stage in (PipelineStage.EXTRACTING, PipelineStage.EXTRACTED):\n                transition_by_id(db, work_item_id=child.id, to_stage=stage, organization_id=split.organization_id)\n            job_service.enqueue(db, job_type="document.enrich", organization_id=split.organization_id,\n                                payload={"work_item_id": str(child.id), "organization_id": str(split.organization_id),\n                                         "workspace_id": str(split.workspace_id)},\n                                idempotency_key=f"document.enrich:{child.id}")\n            segment.child_work_item_id = child.id\n            db.flush([segment])\n            created.append(child.id)\n    superseded = lineage.supersede_parent_mentions(db, split=split)\n    split.status, split.applied_at, split.updated_at = v.STATUS_APPLIED, now(), now()\n    db.flush()\n    _audit(db, split, "apply", split.decided_by_user_id, children=[str(c) for c in created], superseded_mentions=superseded)\n    # ARCH43-S1:emitter-packet-split\n    from app.services import outbox_service\n    from app.services.cases.vocabulary import EVENT_PACKET_SPLIT\n\n    outbox_service.emit_trigger(\n        db, organization_id=split.organization_id, workspace_id=split.workspace_id, event_type=EVENT_PACKET_SPLIT,\n        resource_id=parent.id, idempotency_key=f"{EVENT_PACKET_SPLIT}:{split.id}",\n        payload={"work_item_id": str(parent.id), "split_id": str(split.id), "original_filename": parent.original_filename,\n                 "page_count": split.page_count, "child_count": len(created), "children": [str(c) for c in created]})\n    logger.info("packets.applied", extra={"split_id": str(split.id), "children": len(created)})\n    return {"applied": True, "children": len(created), "superseded_mentions": superseded}\n\n\ndef render_thumbnail(work_item: WorkItem, page: int, scale: float = 0.35) -> bytes:\n    """ARCH43-S1:thumbnail. Render one page of a PDF packet to PNG bytes."""\n    import pypdfium2 as pdfium\n\n    from app.core.storage import get_storage_driver\n\n    if (work_item.file_type or "").split(";")[0].strip().lower() != v.PDF_MIME:\n        raise PacketError("NOT_PDF", "Only PDF packets have page thumbnails.")\n    pdf = pdfium.PdfDocument(get_storage_driver().get(work_item.stored_filename))\n    try:\n        if not 1 <= page <= len(pdf):\n            raise PacketError("NO_PAGE", "page out of range")\n        image = pdf[page - 1].render(scale=scale).to_pil()\n        buffer = io.BytesIO()\n        image.save(buffer, format="PNG", optimize=True)\n        return buffer.getvalue()\n    finally:\n        pdf.close()\n\n\ndef mark_failed(db: Session, *, split_id: uuid.UUID, reason: str) -> None:\n    split = db.get(PacketSplit, split_id)\n    if split is not None and split.status in (v.STATUS_APPROVED, v.STATUS_APPLYING):\n        split.status, split.failure_reason, split.updated_at = v.STATUS_FAILED, reason[:2000], now()\n        db.flush()\n\n\n__all__ = ["PacketError", "apply", "approve", "detect", "live_split", "mark_failed", "page_texts", "reject",\n           "replan", "segments_of"]\n'),
    Op(path='backend/app/services/packets/synthetic.py', kind='new', final_sha='a0f48071fd8f82be9a8fe112014ef6c3e89946483d1a4feab9633d60e0ef6e5f',
       variants=(),
       content='"""ARCH43-S1:synthetic — labelled synthetic scanned packets. Pure; seeded.\n\nUsed by scripts/fit_packet_boundaries.py (training seeds) and by\nverify_arch43 T4 (held-out seeds). Each packet is a list of page texts and\nthe set of pages (1-based) on which a new document starts.\n\nThe generator is built to be HARD in the ways real bundles are:\n  * runs of documents of the same type from the same issuer (same letterhead,\n    same title on every page) where only a page-number reset or a changed\n    document number marks the boundary;\n  * documents with no page numbers at all;\n  * duplex blank back sides inside documents and separator sheets between\n    them (neither may start a document);\n  * repeated letterheads on continuation pages, and OCR noise.\n"""\n\nfrom __future__ import annotations\n\nimport random\nfrom typing import Optional\n\nCOMPANIES = ["Acme Supplies Pvt Ltd", "Globex Logistics", "Initech Components", "Contoso Traders", "Umbrella Pharma",\n             "Northwind Foods", "Hooli Networks", "Stark Metals", "Wayne Freight", "Soylent Agro", "Tyrell Textiles",\n             "Cyberdyne Systems", "Vandelay Imports", "Wonka Confectionery", "Oscorp Chemicals"]\nPEOPLE = ["Ravi Kumar", "Priya Sharma", "Arjun Nair", "Meera Iyer", "Sanjay Rao", "Anita Desai", "John Smith",\n          "Fatima Khan", "Wei Chen", "Divya Menon"]\nCITIES = ["Chennai", "Mumbai", "Madurai", "Pune", "Bengaluru", "Rotterdam", "Singapore", "Dubai"]\n\n# type -> (title, number label or None, body line makers, issuer kind, page range)\nTYPES: dict[str, tuple] = {\n    "invoice": ("TAX INVOICE", "Invoice No", "items", "org", (1, 3)),\n    "purchase_order": ("PURCHASE ORDER", "PO No", "items", "org", (1, 3)),\n    "goods_receipt": ("GOODS RECEIPT NOTE", "GRN No", "items", "org", (1, 2)),\n    "delivery_note": ("DELIVERY CHALLAN", "Challan No", "items", "org", (1, 2)),\n    "credit_note": ("CREDIT NOTE", "Credit Note No", "items", "org", (1, 1)),\n    "statement": ("STATEMENT OF ACCOUNT", "Account No", "ledger", "org", (1, 3)),\n    "msa": ("MASTER SERVICES AGREEMENT", "Contract No", "clauses", "org", (3, 8)),\n    "nda": ("MUTUAL NON-DISCLOSURE AGREEMENT", None, "clauses", "org", (2, 4)),\n    "lease": ("LEASE DEED", None, "lease", "person", (2, 5)),\n    "resume": ("CURRICULUM VITAE", None, "cv", "person", (1, 3)),\n    "offer_letter": ("OFFER OF EMPLOYMENT", "Ref No", "letter", "org", (1, 2)),\n    "discharge_summary": ("DISCHARGE SUMMARY", "IP No", "clinical", "person", (1, 3)),\n    "bill_of_lading": ("BILL OF LADING", "B/L No", "shipping", "org", (1, 2)),\n    "customs_manifest": ("CUSTOMS MANIFEST", "Reference No", "shipping", "org", (1, 2)),\n    "passport": ("PASSPORT", None, "id", "person", (1, 1)),\n    "india_id_card": ("AADHAAR - UNIQUE IDENTIFICATION AUTHORITY OF INDIA", None, "id", "person", (1, 1)),\n    "letter": ("", None, "letter", "org", (1, 2)),\n}\n\n_WORDS = ("the parties shall comply with the obligations set out herein and any amendment agreed in writing "\n          "payment shall be made within thirty days of receipt of a valid invoice subject to deduction of tax "\n          "confidential information shall not be disclosed to any third party without prior written consent "\n          "the tenant shall pay the monthly rent on or before the fifth day of each calendar month "\n          "goods were inspected on arrival and found in good order except as noted below").split()\n\n\ndef _sentence(r: random.Random, n: int = 12) -> str:\n    return " ".join(r.choice(_WORDS) for _ in range(n)).capitalize() + "."\n\n\ndef _body(r: random.Random, kind: str, lines: int) -> list[str]:\n    out: list[str] = []\n    for i in range(lines):\n        if kind == "items":\n            out.append(f"{i + 1} {r.choice([\'Steel bolts M8\', \'Copper wire 2mm\', \'Packing tape\', \'Valve assembly\', \'Resin 20kg\', \'Bearing 6204\'])} "\n                       f"{r.randrange(1, 500)} {r.randrange(10, 9000)}.{r.randrange(10, 99)}")\n        elif kind == "ledger":\n            out.append(f"{r.randrange(1, 28):02d}/0{r.randrange(1, 9)}/2026 INV-{r.randrange(1000, 9999)} {r.randrange(100, 90000)}.00")\n        elif kind == "clauses":\n            out.append(f"{r.randrange(1, 30)}.{r.randrange(1, 9)} {_sentence(r, 16)}")\n        elif kind == "lease":\n            out.append(_sentence(r, 14))\n        elif kind == "cv":\n            out.append(r.choice(["Work experience", "Education", "Skills", "Projects"]) + ": " + _sentence(r, 8))\n        elif kind == "clinical":\n            out.append(r.choice(["Diagnosis", "Treatment", "Medication", "Advice", "Follow-up"]) + ": " + _sentence(r, 8))\n        elif kind == "shipping":\n            out.append(r.choice(["Shipper", "Consignee", "Port of loading", "Port of discharge", "Container", "HS code"]) + ": "\n                       + r.choice(COMPANIES + CITIES))\n        elif kind == "id":\n            out.append(r.choice(["Name", "Date of birth", "Date of expiry", "Nationality", "Address"]) + ": " + r.choice(PEOPLE + CITIES))\n        else:\n            out.append(_sentence(r, 12))\n    return out\n\n\ndef _noise(r: random.Random, text: str, rate: float) -> str:\n    if rate <= 0:\n        return text\n    chars = list(text)\n    for i, ch in enumerate(chars):\n        if ch.isalnum() and r.random() < rate:\n            chars[i] = r.choice("0O1lI5S8B ")\n    return "".join(chars)\n\n\ndef _document(r: random.Random, doc_type: str, issuer: str, number: str) -> list[str]:\n    title, label, kind, _, (lo, hi) = TYPES[doc_type]\n    pages = r.randint(lo, hi)\n    style = r.choices(["none", "page_of", "slash", "page"], weights=[40, 30, 15, 15])[0]\n    at_top = r.random() < 0.3\n    repeat_header = r.random() < 0.6\n    repeat_title = r.random() < 0.45\n    out: list[str] = []\n    for k in range(1, pages + 1):\n        lines: list[str] = []\n        if k == 1 or repeat_header:\n            lines += [issuer.upper(), f"{r.randrange(1, 300)} Industrial Estate, {r.choice(CITIES)}"]\n        if title and (k == 1 or repeat_title):\n            lines.append(title if k == 1 else f"{title} (continued)" if r.random() < 0.5 else title)\n        if label and (k == 1 or repeat_header):\n            lines.append(f"{label}: {number}")\n        if k == 1 and doc_type == "letter":\n            lines.append(f"Dear {r.choice(PEOPLE)},")\n        lines += _body(r, kind, r.randint(6, 18))\n        marker = {"none": None, "page_of": f"Page {k} of {pages}", "slash": f"{k}/{pages}", "page": f"Page {k}"}[style]\n        if marker:\n            lines = [marker] + lines if at_top else lines + [marker]\n        out.append("\\n".join(lines))\n    return out\n\n\ndef packet(seed: int, documents: Optional[int] = None, noise: float = 0.015) -> tuple[list[str], set[int]]:\n    r = random.Random(seed)\n    count = documents or r.randint(3, 14)\n    texts: list[str] = []\n    starts: set[int] = set()\n    prev: Optional[tuple[str, str]] = None\n    for d in range(count):\n        if prev is not None and r.random() < 0.3:\n            doc_type, issuer = prev  # a run: same type, same issuer, same letterhead\n        else:\n            doc_type = r.choice(list(TYPES))\n            issuer = r.choice(PEOPLE) if TYPES[doc_type][3] == "person" else r.choice(COMPANIES)\n        number = f"{doc_type[:3].upper()}-{r.randrange(2024, 2027)}-{r.randrange(100, 99999)}"\n        prev = (doc_type, issuer)\n        if d > 0 and r.random() < 0.06:\n            texts.append("DOCUMENT SEPARATOR SHEET\\nPATCH T")\n        starts.add(len(texts) + 1)\n        for page in _document(r, doc_type, issuer, number):\n            texts.append(_noise(r, page, noise))\n            if r.random() < 0.08:\n                texts.append(r.choice(["", " ", ". ,", "\\n"]))  # a duplex back side\n    return texts, starts\n\n\ndef corpus(seeds: range) -> list[tuple[list[str], set[int]]]:\n    return [packet(s) for s in seeds]\n\n\nTRAIN_SEEDS = range(1000, 1400)\nHELD_OUT_SEEDS = range(90000, 90150)\n\n__all__ = ["HELD_OUT_SEEDS", "TRAIN_SEEDS", "TYPES", "corpus", "packet"]\n'),
