    Op(path='frontend/src/pages/cases/CaseDetail.tsx', kind='new', final_sha='d920935158e62a8cad71b34dc349ad347bbcb2cb24abc1bdc5f481101c25689a',
       variants=(),
       content='/**\n * ARCH43-S2:page-case-detail — one case: the checklist of required documents\n * (with a single-use upload link for what is missing), the documents, and the\n * consistency matrix (every rule, its outcome and the two values compared).\n */\nimport React, { useState } from "react";\nimport { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";\nimport { Link, useParams } from "react-router-dom";\nimport { CheckCircle2, CircleDashed, Loader2 } from "lucide-react";\n\nimport { CAPABILITY } from "@/constants/capabilities";\nimport { BUTTON_PRIMARY, BUTTON_SECONDARY, HINT, INPUT, PAGE_TITLE, SCROLL_X, SECTION_TITLE, SURFACE, TABLE_HEAD, TABLE_ROW } from "@/components/ui/primitives";\nimport { useActiveWorkspace } from "@/hooks/useActiveWorkspace";\nimport { useCapabilityAccess } from "@/hooks/useCapabilityAccess";\nimport { casesPath } from "@/routes/tenantPaths";\nimport {\n  addCaseDocument, caseKeys, closeCase, evaluateCase, getCase, removeCaseDocument, requestDocument, revokeDocumentRequest,\n} from "@/services/api/cases";\nimport { errorMessage } from "@/services/api/errors";\nimport { CASE_STATUS_LABELS, type RuleOutcome } from "@/types/cases";\n\nconst OUTCOME_STYLE: Readonly<Record<RuleOutcome, string>> = {\n  PASS: "bg-green-100 text-green-800", FAIL: "bg-red-100 text-red-800", MISSING: "bg-muted text-muted-foreground", ERROR: "bg-amber-100 text-amber-800",\n};\n\nconst CaseDetailPage: React.FC = () => {\n  const workspace = useActiveWorkspace();\n  const workspaceId = workspace?.workspaceId ?? "";\n  const { orgSlug = "", workspaceSlug = "", caseId = "" } = useParams<{ orgSlug: string; workspaceSlug: string; caseId: string }>();\n  const capability = useCapabilityAccess(workspace?.organizationId ?? "", CAPABILITY.caseIntelligence);\n  const client = useQueryClient();\n  const key = caseKeys.detail(workspaceId, caseId);\n  const query = useQuery({ queryKey: key, queryFn: () => getCase(workspaceId, caseId), enabled: Boolean(workspaceId && caseId && capability.granted) });\n  const [link, setLink] = useState<string | null>(null);\n  const [addId, setAddId] = useState("");\n  const done = (): void => { void client.invalidateQueries({ queryKey: key }); void client.invalidateQueries({ queryKey: caseKeys.all(workspaceId) }); };\n  const evaluate = useMutation({ mutationFn: () => evaluateCase(workspaceId, caseId), onSuccess: done });\n  const close = useMutation({ mutationFn: () => closeCase(workspaceId, caseId), onSuccess: done });\n  const add = useMutation({ mutationFn: () => addCaseDocument(workspaceId, caseId, addId.trim()), onSuccess: () => { setAddId(""); done(); } });\n  const remove = useMutation({ mutationFn: (id: string) => removeCaseDocument(workspaceId, caseId, id), onSuccess: done });\n  const request = useMutation({\n    mutationFn: (docType: string) => requestDocument(workspaceId, caseId, docType, ""),\n    onSuccess: (created) => { setLink(`${window.location.origin}${created.upload_path}`); done(); },\n  });\n  const revoke = useMutation({ mutationFn: (id: string) => revokeDocumentRequest(workspaceId, caseId, id), onSuccess: done });\n  const failure = evaluate.error ?? close.error ?? add.error ?? remove.error ?? request.error ?? revoke.error;\n\n  if (!capability.granted) {return <p className={`${SURFACE} m-4 p-6 text-sm`}>Case intelligence is included on the Business and Enterprise plans.</p>;}\n  if (query.isLoading) {return <Loader2 className="m-6 h-5 w-5 animate-spin" aria-label="Loading" />;}\n  if (query.isError || !query.data) {return <p className="m-4 text-sm text-destructive">{errorMessage(query.error, "The case could not be loaded.")}</p>;}\n  const { case: c, checklist, documents, rules, requests, template } = query.data;\n  const closed = c.status === "CLOSED";\n  return (\n    <div className="space-y-4 p-4">\n      <header className="flex flex-wrap items-center gap-2">\n        <h1 className={PAGE_TITLE}>{c.title}</h1>\n        <span className="rounded bg-muted px-2 py-0.5 text-xs font-semibold">{CASE_STATUS_LABELS[c.status]}</span>\n        <span className={HINT}>{template.name} v{template.version} · {Math.round(c.completeness * 100)}% complete</span>\n        <Link to={casesPath(orgSlug, workspaceSlug)} className="ml-auto text-sm underline">All cases</Link>\n      </header>\n      {failure ? <p className="text-sm text-destructive">{errorMessage(failure, "The request failed.")}</p> : null}\n      {link ? (\n        <p className={`${SURFACE} break-all p-3 text-sm`}>\n          Send this link to the person who has the document. It works once and is shown only now: <code>{link}</code>\n        </p>\n      ) : null}\n      <section className={`${SURFACE} space-y-2 p-4`} aria-label="Checklist">\n        <h2 className={SECTION_TITLE}>Checklist</h2>\n        <ul className="space-y-1 text-sm">\n          {checklist.map((slot) => (\n            <li key={slot.doc_type} className="flex flex-wrap items-center gap-2">\n              {slot.satisfied ? <CheckCircle2 className="h-4 w-4 text-green-600" aria-label="present" /> : <CircleDashed className="h-4 w-4" aria-label="missing" />}\n              <span>{slot.label}</span>\n              <span className={HINT}>{slot.present}/{slot.min_count}</span>\n              {!slot.satisfied && !closed && (\n                <button type="button" className={BUTTON_SECONDARY} disabled={request.isPending} onClick={() => request.mutate(slot.doc_type)}>\n                  Request upload link\n                </button>\n              )}\n            </li>\n          ))}\n        </ul>\n      </section>\n      <section className={`${SURFACE} ${SCROLL_X} p-4`} aria-label="Consistency matrix">\n        <h2 className={SECTION_TITLE}>Consistency</h2>\n        <table className="mt-2 w-full text-sm">\n          <thead><tr className={TABLE_HEAD}><th className="p-2 text-left">Rule</th><th className="p-2">Check</th><th className="p-2">Result</th><th className="p-2 text-left">Left</th><th className="p-2 text-left">Right</th></tr></thead>\n          <tbody>\n            {rules.map((r) => (\n              <tr key={r.rule_id} className={TABLE_ROW}>\n                <td className="p-2">{r.label}</td>\n                <td className="p-2 text-center font-mono text-xs">{r.op}</td>\n                <td className="p-2 text-center"><span className={`rounded px-2 py-0.5 text-xs font-bold ${OUTCOME_STYLE[r.outcome]}`}>{r.outcome}</span></td>\n                <td className="p-2">{r.left_value ?? "—"}</td>\n                <td className="p-2">{r.right_value ?? "—"}</td>\n              </tr>\n            ))}\n            {rules.length === 0 ? <tr><td colSpan={5} className="p-3 text-center text-muted-foreground">This template has no rules.</td></tr> : null}\n          </tbody>\n        </table>\n      </section>\n      <section className={`${SURFACE} space-y-2 p-4`} aria-label="Documents">\n        <h2 className={SECTION_TITLE}>Documents</h2>\n        <ul className="space-y-1 text-sm">\n          {documents.map((d) => (\n            <li key={d.work_item_id} className="flex flex-wrap items-center gap-2">\n              <span>{d.original_filename}</span><span className={HINT}>{d.document_type.replace(/_/g, " ")} · {d.source.toLowerCase()}</span>\n              {!closed && <button type="button" className="text-xs underline" onClick={() => remove.mutate(d.work_item_id)}>Remove</button>}\n            </li>\n          ))}\n        </ul>\n        {!closed && (\n          <div className="flex gap-2">\n            <input className={INPUT} aria-label="Document id" placeholder="Document id" value={addId} onChange={(e) => setAddId(e.target.value)} />\n            <button type="button" className={BUTTON_SECONDARY} disabled={!addId.trim() || add.isPending} onClick={() => add.mutate()}>Add document</button>\n          </div>\n        )}\n      </section>\n      {requests.length > 0 && (\n        <section className={`${SURFACE} space-y-1 p-4 text-sm`} aria-label="Requests">\n          <h2 className={SECTION_TITLE}>Upload requests</h2>\n          {requests.map((r) => (\n            <p key={r.id} className="flex flex-wrap items-center gap-2">\n              {r.document_type.replace(/_/g, " ")} · {r.status.toLowerCase()} · expires {new Date(r.expires_at).toLocaleString()}\n              {r.status === "OPEN" && <button type="button" className="text-xs underline" onClick={() => revoke.mutate(r.id)}>Withdraw</button>}\n            </p>\n          ))}\n        </section>\n      )}\n      {!closed && (\n        <div className="flex gap-2">\n          <button type="button" className={BUTTON_SECONDARY} disabled={evaluate.isPending} onClick={() => evaluate.mutate()}>Re-check</button>\n          <button type="button" className={BUTTON_PRIMARY} disabled={close.isPending} onClick={() => close.mutate()}>Close case</button>\n        </div>\n      )}\n    </div>\n  );\n};\n\nexport default CaseDetailPage;\n'),
    Op(path='frontend/src/pages/cases/Cases.tsx', kind='new', final_sha='f4ff7bd56ca3f1aa30cb6fbae7dce824efa0e597b1a018d6a3b5a9384840c13a',
       variants=(),
       content='/**\n * ARCH43-S2:page-cases — the case board. Cases are assembled automatically\n * from published templates (by ARCH-42 entity or ARCH-38 batch) or opened by\n * hand; each column is a status. Templates are drafted as JSON, published\n * (immutable from then on) and retired here.\n */\nimport React, { useState } from "react";\nimport { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";\nimport { Link, useParams } from "react-router-dom";\nimport { FolderKanban, Loader2, Lock } from "lucide-react";\n\nimport { CAPABILITY } from "@/constants/capabilities";\nimport { BUTTON_PRIMARY, BUTTON_SECONDARY, HINT, INPUT, PAGE_TITLE, SECTION_TITLE, SURFACE, SURFACE_INSET } from "@/components/ui/primitives";\nimport { useActiveWorkspace } from "@/hooks/useActiveWorkspace";\nimport { useCapabilityAccess } from "@/hooks/useCapabilityAccess";\nimport { casePath, packetSplitsPath } from "@/routes/tenantPaths";\nimport {\n  caseKeys, createCase, createCaseTemplate, listCases, listCaseTemplates, publishCaseTemplate, retireCaseTemplate,\n} from "@/services/api/cases";\nimport { errorMessage } from "@/services/api/errors";\nimport { CASE_STATUSES, CASE_STATUS_LABELS, type TemplateWrite } from "@/types/cases";\n\nconst EXAMPLE: TemplateWrite = {\n  key: "purchase-file",\n  name: "Purchase file",\n  assembly_key: "ENTITY",\n  entity_kind: "ORGANIZATION",\n  entity_role: "vendor",\n  required_documents: [{ doc_type: "purchase_order" }, { doc_type: "invoice" }, { doc_type: "goods_receipt" }],\n  rules: [\n    { id: "vendor-matches", op: "FUZZY_EQUAL", label: "Invoice vendor matches the PO",\n      left: { doc_type: "invoice", field: "vendor_name" }, right: { doc_type: "purchase_order", field: "vendor_name" } },\n    { id: "invoiced-within-po", op: "SUM_EQUALS", label: "Invoices add up to the PO total",\n      terms: [{ doc_type: "invoice", field: "total_amount" }], right: { doc_type: "purchase_order", field: "total_amount" } },\n    { id: "invoice-after-po", op: "DATE_ORDER", label: "Invoice dated on or after the PO",\n      left: { doc_type: "purchase_order", field: "po_date" }, right: { doc_type: "invoice", field: "invoice_date" } },\n  ],\n};\n\nconst Cases: React.FC = () => {\n  const workspace = useActiveWorkspace();\n  const workspaceId = workspace?.workspaceId ?? "";\n  const { orgSlug = "", workspaceSlug = "" } = useParams<{ orgSlug: string; workspaceSlug: string }>();\n  const capability = useCapabilityAccess(workspace?.organizationId ?? "", CAPABILITY.caseIntelligence);\n  const enabled = Boolean(workspaceId && capability.granted);\n  const client = useQueryClient();\n  const cases = useQuery({ queryKey: caseKeys.all(workspaceId), queryFn: () => listCases(workspaceId), enabled });\n  const templates = useQuery({ queryKey: caseKeys.templates(workspaceId), queryFn: () => listCaseTemplates(workspaceId), enabled });\n  const [draft, setDraft] = useState(JSON.stringify(EXAMPLE, null, 2));\n  const [manual, setManual] = useState({ templateId: "", title: "" });\n  const refresh = (): void => { void client.invalidateQueries({ queryKey: caseKeys.all(workspaceId) }); };\n  const create = useMutation({ mutationFn: () => createCaseTemplate(workspaceId, JSON.parse(draft) as TemplateWrite), onSuccess: refresh });\n  const publish = useMutation({ mutationFn: (id: string) => publishCaseTemplate(workspaceId, id), onSuccess: refresh });\n  const retire = useMutation({ mutationFn: (id: string) => retireCaseTemplate(workspaceId, id), onSuccess: refresh });\n  const open = useMutation({ mutationFn: () => createCase(workspaceId, manual.templateId, manual.title), onSuccess: refresh });\n  const failure = create.error ?? publish.error ?? retire.error ?? open.error;\n\n  if (!capability.granted) {\n    return (\n      <section className={`${SURFACE} mx-auto mt-6 max-w-2xl space-y-3 p-6`} aria-labelledby="cases-lock">\n        <div className="flex items-center gap-2"><Lock className="h-4 w-4" aria-hidden /><h2 id="cases-lock" className={SECTION_TITLE}>Case intelligence</h2></div>\n        <p className="text-sm text-muted-foreground">\n          Split scanned bundles into documents and assemble them into cases — vendor files, loan packets, claims — with a\n          checklist of what is missing and rules that catch documents that disagree.\n        </p>\n        <p className={HINT}>It&apos;s included on the Business and Enterprise plans.</p>\n      </section>\n    );\n  }\n  const published = (templates.data ?? []).filter((t) => t.status === "PUBLISHED");\n  return (\n    <div className="space-y-5 p-4">\n      <header className="flex flex-wrap items-center gap-2">\n        <FolderKanban className="h-5 w-5" aria-hidden />\n        <h1 className={PAGE_TITLE}>Cases</h1>\n        <Link to={packetSplitsPath(orgSlug, workspaceSlug)} className="ml-auto text-sm underline">Scanned packets</Link>\n      </header>\n      {failure ? <p className="text-sm text-destructive">{errorMessage(failure, "The request failed.")}</p> : null}\n      {cases.isLoading ? <Loader2 className="h-5 w-5 animate-spin" aria-label="Loading" /> : null}\n      <div className="grid gap-3 md:grid-cols-4" role="list" aria-label="Case board">\n        {CASE_STATUSES.map((status) => (\n          <section key={status} className={`${SURFACE_INSET} min-h-40 space-y-2 p-2`} role="listitem" aria-label={CASE_STATUS_LABELS[status]}>\n            <h2 className="text-xs font-bold uppercase tracking-wide">\n              {CASE_STATUS_LABELS[status]} · {cases.data?.counts_by_status[status] ?? 0}\n            </h2>\n            {(cases.data?.items ?? []).filter((c) => c.status === status).map((c) => (\n              <Link key={c.id} to={casePath(orgSlug, workspaceSlug, c.id)} className={`${SURFACE} block space-y-1 p-2 text-sm hover:bg-muted`}>\n                <span className="font-semibold">{c.title}</span>\n                <span className={`block ${HINT}`}>\n                  {c.documents} documents · {Math.round(c.completeness * 100)}% complete{c.failed_rules ? ` · ${c.failed_rules} rule(s) failed` : ""}\n                </span>\n              </Link>\n            ))}\n          </section>\n        ))}\n      </div>\n      <section className={`${SURFACE} space-y-3 p-4`}>\n        <h2 className={SECTION_TITLE}>Templates</h2>\n        <ul className="space-y-1 text-sm">\n          {(templates.data ?? []).map((t) => (\n            <li key={t.id} className="flex flex-wrap items-center gap-2">\n              <span className="font-mono">{t.key} v{t.version}</span><span>{t.name}</span>\n              <span className="rounded bg-muted px-1.5 text-xs">{t.status}</span>\n              <span className={HINT}>{t.required_documents.length} documents · {t.rules.length} rules · by {t.assembly_key.toLowerCase()}</span>\n              {t.status === "DRAFT" && <button type="button" className={BUTTON_SECONDARY} onClick={() => publish.mutate(t.id)}>Publish</button>}\n              {t.status === "PUBLISHED" && <button type="button" className={BUTTON_SECONDARY} onClick={() => retire.mutate(t.id)}>Retire</button>}\n            </li>\n          ))}\n        </ul>\n        <label className="block space-y-1 text-sm">\n          <span>New template (JSON). Published templates cannot change; a new draft of the same key becomes the next version.</span>\n          <textarea className={`${INPUT} h-56 w-full font-mono text-xs`} value={draft} onChange={(e) => setDraft(e.target.value)} />\n        </label>\n        <button type="button" className={BUTTON_PRIMARY} disabled={create.isPending} onClick={() => create.mutate()}>Save draft</button>\n      </section>\n      <section className={`${SURFACE} space-y-2 p-4`}>\n        <h2 className={SECTION_TITLE}>Open a case by hand</h2>\n        <div className="flex flex-wrap gap-2">\n          <select className={INPUT} aria-label="Template" value={manual.templateId} onChange={(e) => setManual({ ...manual, templateId: e.target.value })}>\n            <option value="">Template…</option>\n            {published.map((t) => <option key={t.id} value={t.id}>{t.name} v{t.version}</option>)}\n          </select>\n          <input className={INPUT} aria-label="Case title" placeholder="Title" value={manual.title} onChange={(e) => setManual({ ...manual, title: e.target.value })} />\n          <button type="button" className={BUTTON_PRIMARY} disabled={!manual.templateId || !manual.title || open.isPending} onClick={() => open.mutate()}>Open case</button>\n        </div>\n      </section>\n    </div>\n  );\n};\n\nexport default Cases;\n'),
    Op(path='frontend/src/pages/packets/PacketSplits.tsx', kind='new', final_sha='a30d0081f842ece22a0fde7bae1d3bc9cf8ee46d4c95c807e1bca12893ebfdaf',
       variants=(),
       content='/** ARCH43-S2:page-packet-splits — every split plan in the workspace, newest first. */\nimport React from "react";\nimport { useQuery } from "@tanstack/react-query";\nimport { Link, useParams } from "react-router-dom";\nimport { Loader2, Scissors } from "lucide-react";\n\nimport { CAPABILITY } from "@/constants/capabilities";\nimport { HINT, PAGE_TITLE, SCROLL_X, SURFACE, TABLE_HEAD, TABLE_ROW } from "@/components/ui/primitives";\nimport { useActiveWorkspace } from "@/hooks/useActiveWorkspace";\nimport { useCapabilityAccess } from "@/hooks/useCapabilityAccess";\nimport { packetSplitPath } from "@/routes/tenantPaths";\nimport { caseKeys } from "@/services/api/cases";\nimport { errorMessage } from "@/services/api/errors";\nimport { listPacketSplits } from "@/services/api/packets";\n\nconst PacketSplits: React.FC = () => {\n  const workspace = useActiveWorkspace();\n  const workspaceId = workspace?.workspaceId ?? "";\n  const { orgSlug = "", workspaceSlug = "" } = useParams<{ orgSlug: string; workspaceSlug: string }>();\n  const capability = useCapabilityAccess(workspace?.organizationId ?? "", CAPABILITY.caseIntelligence);\n  const query = useQuery({\n    queryKey: caseKeys.splits(workspaceId),\n    queryFn: () => listPacketSplits(workspaceId),\n    enabled: Boolean(workspaceId && capability.granted),\n  });\n  if (!capability.granted) {\n    return <p className={`${SURFACE} p-6 text-sm`}>The packet dicer is included on the Business and Enterprise plans.</p>;\n  }\n  return (\n    <div className="space-y-4 p-4">\n      <header className="flex items-center gap-2">\n        <Scissors className="h-5 w-5" aria-hidden />\n        <h1 className={PAGE_TITLE}>Scanned packets</h1>\n      </header>\n      <p className={HINT}>Multi-page PDFs are checked for document boundaries after processing. Review a plan to divide the packet.</p>\n      {query.isLoading ? <Loader2 className="h-5 w-5 animate-spin" aria-label="Loading" /> : null}\n      {query.isError ? <p className="text-sm text-destructive">{errorMessage(query.error, "Something went wrong.")}</p> : null}\n      {query.data ? (\n        <div className={`${SURFACE} ${SCROLL_X}`}>\n          <table className="w-full text-sm">\n            <thead>\n              <tr className={TABLE_HEAD}>\n                <th className="p-2 text-left">Packet</th><th className="p-2">Pages</th><th className="p-2">Documents</th>\n                <th className="p-2">Status</th><th className="p-2">Certainty</th>\n              </tr>\n            </thead>\n            <tbody>\n              {query.data.items.map((row) => (\n                <tr key={row.id} className={TABLE_ROW}>\n                  <td className="p-2"><Link className="underline" to={packetSplitPath(orgSlug, workspaceSlug, row.id)}>{row.original_filename}</Link></td>\n                  <td className="p-2 text-center">{row.page_count}</td>\n                  <td className="p-2 text-center">{row.segment_count}</td>\n                  <td className="p-2 text-center">{row.status}</td>\n                  <td className="p-2 text-center">{row.certainty !== null ? `${Math.round(row.certainty * 100)}%` : "—"}</td>\n                </tr>\n              ))}\n              {query.data.items.length === 0 ? (\n                <tr><td colSpan={5} className="p-4 text-center text-muted-foreground">No packets yet.</td></tr>\n              ) : null}\n            </tbody>\n          </table>\n        </div>\n      ) : null}\n    </div>\n  );\n};\n\nexport default PacketSplits;\n'),
    Op(path='frontend/src/pages/packets/SplitReview.tsx', kind='new', final_sha='f5e63c17ffa4d697dab2c5cea190ecb85489fb4c9d48b7ecac0381cc3f79a9d6',
       variants=(),
       content='/**\n * ARCH43-S2:page-split-review — divide a scanned packet. Every page is shown\n * as a thumbnail (fetched with the session through useAuthorizedBlobUrl, the\n * ARCH-41 hook, never a public URL). A boundary is the first page of a new\n * document: click the gap before a page to add or remove one, or drag a\n * boundary marker to another gap. Nothing is cut until "Approve split".\n */\nimport React, { useMemo, useState } from "react";\nimport { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";\nimport { Link, useParams } from "react-router-dom";\nimport { Loader2, Scissors } from "lucide-react";\n\nimport { CAPABILITY } from "@/constants/capabilities";\nimport { BUTTON_PRIMARY, BUTTON_SECONDARY, HINT, PAGE_TITLE, SECTION_TITLE, SURFACE } from "@/components/ui/primitives";\nimport { useActiveWorkspace } from "@/hooks/useActiveWorkspace";\nimport { useAuthorizedBlobUrl } from "@/hooks/useAuthorizedBlobUrl";\nimport { useCapabilityAccess } from "@/hooks/useCapabilityAccess";\nimport { packetSplitsPath } from "@/routes/tenantPaths";\nimport { caseKeys } from "@/services/api/cases";\nimport { errorMessage } from "@/services/api/errors";\nimport { approvePacketSplit, correctPacketSplit, getPacketSplit, rejectPacketSplit } from "@/services/api/packets";\nimport type { PageScore } from "@/types/packets";\n\nconst PageThumb: React.FC<{ readonly workspaceId: string; readonly splitId: string; readonly score: PageScore }> = ({\n  workspaceId, splitId, score,\n}) => {\n  const blob = useAuthorizedBlobUrl(\n    `/workspaces/${encodeURIComponent(workspaceId)}/packet-splits/${encodeURIComponent(splitId)}/pages/${score.page}/thumbnail`,\n  );\n  return (\n    <figure className="w-32 shrink-0 space-y-1">\n      <div className="flex h-40 items-center justify-center overflow-hidden rounded border border-border bg-white">\n        {blob.url ? (\n          <img src={blob.url} alt={`Page ${score.page}`} className="max-h-full max-w-full" />\n        ) : (\n          <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" aria-label="Loading page" />\n        )}\n      </div>\n      <figcaption className="text-center text-[11px] text-muted-foreground">\n        p{score.page} · {score.doc_type === "other" ? "—" : score.doc_type.replace(/_/g, " ")}\n      </figcaption>\n    </figure>\n  );\n};\n\nconst SplitReview: React.FC = () => {\n  const workspace = useActiveWorkspace();\n  const workspaceId = workspace?.workspaceId ?? "";\n  const { orgSlug = "", workspaceSlug = "", splitId = "" } = useParams<{ orgSlug: string; workspaceSlug: string; splitId: string }>();\n  const capability = useCapabilityAccess(workspace?.organizationId ?? "", CAPABILITY.caseIntelligence);\n  const client = useQueryClient();\n  const query = useQuery({\n    queryKey: caseKeys.split(workspaceId, splitId),\n    queryFn: () => getPacketSplit(workspaceId, splitId),\n    enabled: Boolean(workspaceId && splitId && capability.granted),\n  });\n  const [edited, setEdited] = useState<number[] | null>(null);\n  const [dragging, setDragging] = useState<number | null>(null);\n  const detail = query.data;\n  const original = useMemo(() => (detail ? detail.segments.slice(1).map((s) => s.page_start) : []), [detail]);\n  const boundaries = edited ?? original;\n  const editable = detail?.split.status === "PROPOSED" || detail?.split.status === "SINGLE";\n  const refresh = (): void => {\n    setEdited(null);\n    void client.invalidateQueries({ queryKey: caseKeys.split(workspaceId, splitId) });\n    void client.invalidateQueries({ queryKey: caseKeys.splits(workspaceId) });\n  };\n  const save = useMutation({ mutationFn: () => correctPacketSplit(workspaceId, splitId, boundaries), onSuccess: refresh });\n  const approve = useMutation({ mutationFn: () => approvePacketSplit(workspaceId, splitId, boundaries), onSuccess: refresh });\n  const reject = useMutation({ mutationFn: () => rejectPacketSplit(workspaceId, splitId), onSuccess: refresh });\n  const busy = save.isPending || approve.isPending || reject.isPending;\n  const failure = save.error ?? approve.error ?? reject.error;\n\n  const toggle = (page: number): void => {\n    const set = new Set(boundaries);\n    if (set.has(page)) {set.delete(page);}\n    else {set.add(page);}\n    setEdited([...set].sort((a, b) => a - b));\n  };\n  const move = (from: number, to: number): void => {\n    if (from === to || boundaries.includes(to)) {return;}\n    setEdited(boundaries.map((b) => (b === from ? to : b)).sort((a, b) => a - b));\n  };\n\n  if (!capability.granted) {\n    return <p className={`${SURFACE} p-6 text-sm`}>The packet dicer is included on the Business and Enterprise plans.</p>;\n  }\n  if (query.isLoading) {return <Loader2 className="m-6 h-5 w-5 animate-spin" aria-label="Loading" />;}\n  if (query.isError || !detail) {return <p className="text-sm text-destructive">{errorMessage(query.error, "Something went wrong.")}</p>;}\n\n  return (\n    <div className="space-y-4 p-4">\n      <header className="flex flex-wrap items-center gap-3">\n        <Scissors className="h-5 w-5" aria-hidden />\n        <h1 className={PAGE_TITLE}>{detail.split.original_filename}</h1>\n        <span className="rounded bg-muted px-2 py-0.5 text-xs font-semibold">{detail.split.status}</span>\n        <Link to={packetSplitsPath(orgSlug, workspaceSlug)} className="ml-auto text-sm underline">All packets</Link>\n      </header>\n      <p className={HINT}>\n        {detail.split.page_count} pages → {boundaries.length + 1} documents. Click the gap before a page to start (or stop\n        starting) a document there, or drag a marker. Least certain boundary:{" "}\n        {detail.split.certainty !== null ? `${Math.round(detail.split.certainty * 100)}%` : "—"}.\n      </p>\n      <section className={`${SURFACE} p-3`} aria-label="Pages">\n        <div className="flex flex-wrap items-start gap-1">\n          {detail.pages.map((score) => {\n            const isBoundary = boundaries.includes(score.page);\n            return (\n              <React.Fragment key={score.page}>\n                {score.page > 1 && (\n                  <button\n                    type="button"\n                    aria-pressed={isBoundary}\n                    aria-label={`${isBoundary ? "Remove" : "Add"} a document boundary before page ${score.page}`}\n                    disabled={!editable || busy}\n                    onClick={() => toggle(score.page)}\n                    onDragOver={(e) => { if (dragging !== null) {e.preventDefault();} }}\n                    onDrop={(e) => { e.preventDefault(); if (dragging !== null) {move(dragging, score.page);} setDragging(null); }}\n                    className={`flex h-40 w-3 items-center justify-center rounded ${isBoundary ? "bg-primary" : "bg-transparent hover:bg-muted"}`}\n                    title={`p(boundary) = ${Math.round(score.p * 100)}%`}\n                  >\n                    {isBoundary && (\n                      <span\n                        draggable={editable}\n                        onDragStart={() => setDragging(score.page)}\n                        onDragEnd={() => setDragging(null)}\n                        className="block h-10 w-2 cursor-grab rounded bg-primary-foreground/80"\n                      />\n                    )}\n                  </button>\n                )}\n                <PageThumb workspaceId={workspaceId} splitId={splitId} score={score} />\n              </React.Fragment>\n            );\n          })}\n        </div>\n      </section>\n      <section className={`${SURFACE} space-y-2 p-3`}>\n        <h2 className={SECTION_TITLE}>Documents</h2>\n        <ol className="list-decimal space-y-1 pl-6 text-sm">\n          {[1, ...boundaries].map((start, index, all) => {\n            const next = all[index + 1];\n            const end = next !== undefined ? next - 1 : detail.split.page_count;\n            const segment = detail.segments.find((s) => s.page_start === start);\n            return (\n              <li key={start}>\n                Pages {start}–{end}\n                {segment?.document_type ? ` · ${segment.document_type.replace(/_/g, " ")}` : ""}\n                {segment?.child_work_item_id ? " · created" : ""}\n              </li>\n            );\n          })}\n        </ol>\n      </section>\n      {failure ? <p className="text-sm text-destructive">{errorMessage(failure, "Something went wrong.")}</p> : null}\n      {detail.failure_reason ? <p className="text-sm text-destructive">{detail.failure_reason}</p> : null}\n      <div className="flex flex-wrap gap-2">\n        <button type="button" className={BUTTON_SECONDARY} disabled={!editable || busy || edited === null} onClick={() => save.mutate()}>\n          Save boundaries\n        </button>\n        <button type="button" className={BUTTON_PRIMARY} disabled={!editable || busy || boundaries.length === 0} onClick={() => approve.mutate()}>\n          Approve split\n        </button>\n        <button type="button" className={BUTTON_SECONDARY} disabled={!editable || busy} onClick={() => reject.mutate()}>\n          Keep as one document\n        </button>\n        {busy && <Loader2 className="h-4 w-4 animate-spin" aria-label="Working" />}\n      </div>\n    </div>\n  );\n};\n\nexport default SplitReview;\n'),
    Op(path='frontend/src/pages/public/DocumentRequestUpload.tsx', kind='new', final_sha='3b7ed4e957ec87baa216a13687e5b940baa1a906d6e0b028a3886617a67935d9',
       variants=(),
       content='/**\n * ARCH43-S2:page-public-request — the recipient of a missing-document request\n * uploads it here. No account: the single-use link is the credential, and\n * the page shows only the case title and the document type asked for.\n */\nimport React, { useState } from "react";\nimport { useMutation, useQuery } from "@tanstack/react-query";\nimport { useParams } from "react-router-dom";\nimport { CheckCircle2, Loader2, Upload } from "lucide-react";\n\nimport { BUTTON_PRIMARY, HINT, PAGE_TITLE, SURFACE } from "@/components/ui/primitives";\nimport { previewDocumentRequest, uploadRequestedDocument } from "@/services/api/cases";\nimport { errorMessage } from "@/services/api/errors";\n\nconst DocumentRequestUpload: React.FC = () => {\n  const { token = "" } = useParams<{ token: string }>();\n  const [file, setFile] = useState<File | null>(null);\n  const info = useQuery({ queryKey: ["document-request", token], queryFn: () => previewDocumentRequest(token), retry: false, enabled: Boolean(token) });\n  const upload = useMutation({ mutationFn: (f: File) => uploadRequestedDocument(token, f) });\n  return (\n    <main className="mx-auto max-w-lg p-6">\n      <section className={`${SURFACE} space-y-4 p-6`}>\n        <h1 className={PAGE_TITLE}>Upload a requested document</h1>\n        {info.isLoading ? <Loader2 className="h-5 w-5 animate-spin" aria-label="Loading" /> : null}\n        {info.isError ? <p className="text-sm text-destructive">{errorMessage(info.error, "This link is not valid.")}</p> : null}\n        {upload.isSuccess ? (\n          <p className="flex items-center gap-2 text-sm"><CheckCircle2 className="h-4 w-4 text-green-600" aria-hidden /> Received. Thank you — this link is now closed.</p>\n        ) : info.data ? (\n          <>\n            <p className="text-sm">\n              <strong>{info.data.case_title}</strong> needs a <strong>{info.data.document_type.replace(/_/g, " ")}</strong>.\n            </p>\n            <p className={HINT}>This link works once and expires {new Date(info.data.expires_at).toLocaleString()}.</p>\n            <input type="file" accept=".pdf,image/*" aria-label="Document" onChange={(e) => setFile(e.target.files?.[0] ?? null)} />\n            {upload.isError ? <p className="text-sm text-destructive">{errorMessage(upload.error, "This link is not valid.")}</p> : null}\n            <button type="button" className={BUTTON_PRIMARY} disabled={!file || upload.isPending} onClick={() => file && upload.mutate(file)}>\n              {upload.isPending ? <Loader2 className="mr-2 inline h-4 w-4 animate-spin" aria-hidden /> : <Upload className="mr-2 inline h-4 w-4" aria-hidden />}\n              Upload\n            </button>\n          </>\n        ) : null}\n      </section>\n    </main>\n  );\n};\n\nexport default DocumentRequestUpload;\n'),
    Op(path='frontend/src/routes/tenantPaths.ts', kind='edit', final_sha='2947eff5f736059de5354d2c262277c7273a897cf53d1c5f8ea510d1d0ba19b7',
       variants=(('f86d58413cc0ea4db0b56042b58293bdcd7c0e4d199677d80fbd11affd98419b', (('  `${entitiesPath(orgSlug, workspaceSlug)}/${encodeURIComponent(entityId)}`;\n', '  `${entitiesPath(orgSlug, workspaceSlug)}/${encodeURIComponent(entityId)}`;\n\n// ARCH43-S2:case-path-helpers\nexport const casesPath = (orgSlug: string, workspaceSlug: string): string => `${workspacePath(orgSlug, workspaceSlug)}/cases`;\nexport const casePath = (orgSlug: string, workspaceSlug: string, caseId: string): string =>\n  `${casesPath(orgSlug, workspaceSlug)}/${encodeURIComponent(caseId)}`;\nexport const packetSplitsPath = (orgSlug: string, workspaceSlug: string): string =>\n  `${workspacePath(orgSlug, workspaceSlug)}/packet-splits`;\nexport const packetSplitPath = (orgSlug: string, workspaceSlug: string, splitId: string): string =>\n  `${packetSplitsPath(orgSlug, workspaceSlug)}/${encodeURIComponent(splitId)}`;\n'), ('  workspaceEntity: "entities/:entityId",\n', '  workspaceEntity: "entities/:entityId",\n  // ARCH43-S2:route-patterns\n  workspaceCases: "cases",\n  workspaceCase: "cases/:caseId",\n  workspacePacketSplits: "packet-splits",\n  workspacePacketSplit: "packet-splits/:splitId",\n'))),),
       content=''),
    Op(path='frontend/src/services/api/cases.ts', kind='new', final_sha='988df1f436c140956633ad7959e2dc0e68a8f640d5280e34d19f94919d909a14',
       variants=(),
       content='/** ARCH43-S2:api-cases — Case Intelligence. Workspace routes are gated on capability.case_intelligence. */\nimport { apiClient } from "@/services/api/client";\nimport type {\n  CaseDetail, CaseList, CaseStatus, PublicRequestInfo, PublicUploadResult, RequestCreated, RequestRow, TemplateRow, TemplateWrite,\n} from "@/types/cases";\n\nconst ws = (workspaceId: string): string => `/workspaces/${encodeURIComponent(workspaceId)}`;\nconst one = (workspaceId: string, caseId: string): string => `${ws(workspaceId)}/cases/${encodeURIComponent(caseId)}`;\n\nexport const caseKeys = {\n  all: (workspaceId: string) => ["cases", workspaceId] as const,\n  templates: (workspaceId: string) => ["cases", workspaceId, "templates"] as const,\n  detail: (workspaceId: string, caseId: string) => ["cases", workspaceId, "case", caseId] as const,\n  splits: (workspaceId: string) => ["packet-splits", workspaceId] as const,\n  split: (workspaceId: string, splitId: string) => ["packet-splits", workspaceId, splitId] as const,\n};\n\nexport const listCaseTemplates = async (workspaceId: string): Promise<TemplateRow[]> =>\n  (await apiClient.get<TemplateRow[]>(`${ws(workspaceId)}/case-templates`)).data;\nexport const createCaseTemplate = async (workspaceId: string, body: TemplateWrite): Promise<TemplateRow> =>\n  (await apiClient.post<TemplateRow>(`${ws(workspaceId)}/case-templates`, body)).data;\nexport const publishCaseTemplate = async (workspaceId: string, templateId: string): Promise<TemplateRow> =>\n  (await apiClient.post<TemplateRow>(`${ws(workspaceId)}/case-templates/${encodeURIComponent(templateId)}/publish`)).data;\nexport const retireCaseTemplate = async (workspaceId: string, templateId: string): Promise<TemplateRow> =>\n  (await apiClient.post<TemplateRow>(`${ws(workspaceId)}/case-templates/${encodeURIComponent(templateId)}/retire`)).data;\n\nexport const listCases = async (workspaceId: string, status?: CaseStatus): Promise<CaseList> =>\n  (await apiClient.get<CaseList>(`${ws(workspaceId)}/cases`, { params: status ? { status } : {} })).data;\nexport const createCase = async (workspaceId: string, templateId: string, title: string): Promise<CaseDetail> =>\n  (await apiClient.post<CaseDetail>(`${ws(workspaceId)}/cases`, { template_id: templateId, title })).data;\nexport const getCase = async (workspaceId: string, caseId: string): Promise<CaseDetail> =>\n  (await apiClient.get<CaseDetail>(one(workspaceId, caseId))).data;\nexport const addCaseDocument = async (workspaceId: string, caseId: string, workItemId: string, documentType?: string): Promise<CaseDetail> =>\n  (await apiClient.post<CaseDetail>(`${one(workspaceId, caseId)}/documents`, { work_item_id: workItemId, document_type: documentType || null })).data;\nexport const removeCaseDocument = async (workspaceId: string, caseId: string, workItemId: string): Promise<CaseDetail> =>\n  (await apiClient.delete<CaseDetail>(`${one(workspaceId, caseId)}/documents/${encodeURIComponent(workItemId)}`)).data;\nexport const evaluateCase = async (workspaceId: string, caseId: string): Promise<CaseDetail> =>\n  (await apiClient.post<CaseDetail>(`${one(workspaceId, caseId)}/evaluate`)).data;\nexport const closeCase = async (workspaceId: string, caseId: string): Promise<CaseDetail> =>\n  (await apiClient.post<CaseDetail>(`${one(workspaceId, caseId)}/close`)).data;\nexport const requestDocument = async (workspaceId: string, caseId: string, documentType: string, recipientLabel: string): Promise<RequestCreated> =>\n  (await apiClient.post<RequestCreated>(`${one(workspaceId, caseId)}/requests`, { document_type: documentType, recipient_label: recipientLabel })).data;\nexport const revokeDocumentRequest = async (workspaceId: string, caseId: string, requestId: string): Promise<RequestRow> =>\n  (await apiClient.post<RequestRow>(`${one(workspaceId, caseId)}/requests/${encodeURIComponent(requestId)}/revoke`)).data;\n\nexport const previewDocumentRequest = async (token: string): Promise<PublicRequestInfo> =>\n  (await apiClient.get<PublicRequestInfo>(`/public/document-requests/${encodeURIComponent(token)}`)).data;\nexport const uploadRequestedDocument = async (token: string, file: File): Promise<PublicUploadResult> => {\n  const form = new FormData();\n  form.append("file", file);\n  return (await apiClient.post<PublicUploadResult>(`/public/document-requests/${encodeURIComponent(token)}`, form)).data;\n};\n'),
    Op(path='frontend/src/services/api/packets.ts', kind='new', final_sha='930818bb9b676a797d3613ee1ea0d5785ff806f7af4d5dba552cc0d96ab8d87f',
       variants=(),
       content='/** ARCH43-S2:api-client — the Universal Packet Dicer. Every route is gated on capability.case_intelligence. */\nimport { apiClient } from "@/services/api/client";\nimport type { PacketSplitDetail, PacketSplitList, PacketSplitStatus, WorkItemLineage } from "@/types/packets";\n\nconst ws = (workspaceId: string): string => `/workspaces/${encodeURIComponent(workspaceId)}`;\nconst split = (workspaceId: string, splitId: string): string =>\n  `${ws(workspaceId)}/packet-splits/${encodeURIComponent(splitId)}`;\n\nexport const listPacketSplits = async (workspaceId: string, status?: PacketSplitStatus): Promise<PacketSplitList> =>\n  (await apiClient.get<PacketSplitList>(`${ws(workspaceId)}/packet-splits`, { params: status ? { status } : {} })).data;\n\nexport const getPacketSplit = async (workspaceId: string, splitId: string): Promise<PacketSplitDetail> =>\n  (await apiClient.get<PacketSplitDetail>(split(workspaceId, splitId))).data;\n\nexport const detectPacketSplit = async (workspaceId: string, workItemId: string, force = false): Promise<PacketSplitDetail> =>\n  (await apiClient.post<PacketSplitDetail>(\n    `${ws(workspaceId)}/work-items/${encodeURIComponent(workItemId)}/packet-split`, undefined, { params: { force } },\n  )).data;\n\nexport const correctPacketSplit = async (\n  workspaceId: string, splitId: string, boundaries: readonly number[],\n): Promise<PacketSplitDetail> =>\n  (await apiClient.put<PacketSplitDetail>(`${split(workspaceId, splitId)}/boundaries`, { boundaries })).data;\n\nexport const approvePacketSplit = async (\n  workspaceId: string, splitId: string, boundaries?: readonly number[],\n): Promise<PacketSplitDetail> =>\n  (await apiClient.post<PacketSplitDetail>(`${split(workspaceId, splitId)}/approve`, boundaries ? { boundaries } : {})).data;\n\nexport const rejectPacketSplit = async (workspaceId: string, splitId: string): Promise<PacketSplitDetail> =>\n  (await apiClient.post<PacketSplitDetail>(`${split(workspaceId, splitId)}/reject`)).data;\n\nexport const getWorkItemLineage = async (workspaceId: string, workItemId: string): Promise<WorkItemLineage> =>\n  (await apiClient.get<WorkItemLineage>(`${ws(workspaceId)}/work-items/${encodeURIComponent(workItemId)}/lineage`)).data;\n'),
